/// Button.iconName update. The create arm leaves the icon in one of two
/// shapes — a bare GtkImage (icon-only) or an AdwButtonContent (icon+label) —
/// so retarget whichever is there rather than rebuilding the child, which
/// would drop the badge suffix and the size classes.
///
/// A button already carrying `iconData` is left alone: image bytes beat a
/// theme name at create, and that precedence has to hold on every later frame
/// too.
fn ndButtonSetIconName(button: *gtk.Button, icon: []const u8, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    if (gobject.Object.getData(asObject(button), ND_BUTTON_ICON_IMAGE) != null) return;
    const content = ndButtonContent(button) orelse return;
    if (gobject.ext.isA(content, adw.ButtonContent)) {
        adw.ButtonContent.setIconName(@ptrCast(@alignCast(content)), ndicons.symbolic(dupeZ(icon)));
    } else if (gobject.ext.isA(content, gtk.Image)) {
        gtk.Image.setFromIconName(@ptrCast(@alignCast(content)), ndicons.symbolic(dupeZ(icon)));
    }
}

/// The text the button currently renders, whichever child shape holds it
/// ("" for an icon-only button). Borrowed from the widget, so copy it before
/// replacing the content it lives in.
fn ndButtonLabelText(button: *gtk.Button) []const u8 {
    const content = ndButtonContent(button) orelse return "";
    if (gobject.ext.isA(content, adw.ButtonContent)) {
        return std.mem.span(adw.ButtonContent.getLabel(@ptrCast(@alignCast(content))));
    }
    if (gobject.ext.isA(content, gtk.Label)) {
        return std.mem.span(gtk.Label.getText(@ptrCast(@alignCast(content))));
    }
    return "";
}

// The GtkImage a Button's iconData renders into (qdata key), so an update
// retargets that image instead of rebuilding the child on every frame.
const ND_BUTTON_ICON_IMAGE = "nd-button-icon-image";

/// Button.iconData: an icon from raw image bytes (a `data:` URL or bare
/// base64) where no theme name reaches, e.g. a favicon. Runs after the
/// iconName arm, so image bytes win. Unlike iconName this updates: the first
/// call rebuilds the content around the decoded image, keeping whatever label
/// the button already shows, and later calls retarget that image's paintable.
/// An undecodable payload leaves the button as it was (ndicons warns).
fn ndButtonApplyIconData(button: *gtk.Button, data: []const u8, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    if (gobject.Object.getData(asObject(button), ND_BUTTON_ICON_IMAGE)) |ptr| {
        const texture = ndicons.textureFromData(data, "Button") orelse return;
        defer gobject.Object.unref(texture.as(gobject.Object));
        gtk.Image.setFromPaintable(@ptrCast(@alignCast(ptr)), texture.as(gdk.Paintable));
        return;
    }
    const img = ndicons.imageFromData(data, "Button") orelse return;
    const label = ndButtonLabelText(button);
    const content: *gtk.Widget = if (label.len == 0) blk: {
        // The square metrics of an icon-only button come from this class,
        // which only gtk_button_set_icon_name/set_label would maintain.
        gtk.Widget.addCssClass(button.as(gtk.Widget), "image-button");
        gtk.Widget.removeCssClass(button.as(gtk.Widget), "text-button");
        break :blk img.as(gtk.Widget);
    } else blk: {
        const box = gtk.Box.new(.horizontal, 6);
        gtk.Box.append(box, img.as(gtk.Widget));
        gtk.Box.append(box, gtk.Label.new(dupeZ(label)).as(gtk.Widget));
        break :blk box.as(gtk.Widget);
    };
    ndButtonReplaceContent(button, content);
    gobject.Object.setData(asObject(button), ND_BUTTON_ICON_IMAGE, img);
}

// The GtkImage in a Row's prefix slot (qdata key), whichever of iconName /
// iconData put it there — an iconData update retargets it rather than
// stacking a second prefix icon.
const ND_ROW_ICON_IMAGE = "nd-row-icon-image";

/// Row.iconData: the AdwActionRow peer of ndButtonApplyIconData. Runs after
/// the iconName arm and retargets that prefix image when there is one, so
/// image bytes win over a theme name on create and on update alike.
fn ndRowApplyIconData(row: *adw.ActionRow, data: []const u8) void {
    const texture = ndicons.textureFromData(data, "Row") orelse return;
    defer gobject.Object.unref(texture.as(gobject.Object));
    if (gobject.Object.getData(asObject(row), ND_ROW_ICON_IMAGE)) |ptr| {
        gtk.Image.setFromPaintable(@ptrCast(@alignCast(ptr)), texture.as(gdk.Paintable));
        return;
    }
    const img = gtk.Image.newFromPaintable(texture.as(gdk.Paintable));
    gtk.Image.setPixelSize(img, ndicons.data_pixel_size);
    adw.ActionRow.addPrefix(row, img.as(gtk.Widget));
    gobject.Object.setData(asObject(row), ND_ROW_ICON_IMAGE, img);
}

/// Builds a NULL-terminated strv (`?[*]const [*:0]const u8`) from a JSON
/// string array in ONE bulk allocation, for bulk GtkStringList construction
/// (gtk_string_list_new/splice both deep-copy the strings, so the returned
/// buffer only needs to live until that call returns — free it with
/// `std.heap.page_allocator.free(buf)`). O(n), not the O(n^2) per-item
/// StringList.append loop.
fn buildStrv(arr: ?std.json.Array, dupeZ: *const fn ([]const u8) [:0]const u8) []?[*:0]const u8 {
    const items = arr orelse std.json.Array.init(std.heap.page_allocator);
    const buf = std.heap.page_allocator.alloc(?[*:0]const u8, items.items.len + 1) catch @panic("OOM building strv");
    var n: usize = 0;
    for (items.items) |item| {
        if (item != .string) continue;
        buf[n] = dupeZ(item.string);
        n += 1;
    }
    buf[n] = null;
    return buf[0 .. n + 1];
}

/// Builds SourceList's AdwActionRow children from a JSON object array (peer
/// of `buildStrv`, but for objects instead of strings — reuses `propArray`
/// as-is since `std.json.Array` holds untyped `std.json.Value` items
/// regardless of whether they're strings or objects). Rows are appended
/// directly (not bulk-built like `buildStrv`'s strv): AdwActionRow
/// construction is a widget-per-row operation, so there is no bulk GTK
/// primitive to defer to.
fn ndBuildSourceRows(box: *gtk.ListBox, arr: ?std.json.Array, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    const items = arr orelse return;
    for (items.items) |it| {
        if (it != .object) continue;
        const title = if (it.object.get("title")) |t| (if (t == .string) t.string else "") else "";
        const row = adw.ActionRow.new();
        adw.PreferencesRow.setUseMarkup(row.as(adw.PreferencesRow), 0);
        adw.PreferencesRow.setTitle(row.as(adw.PreferencesRow), dupeZ(title));
        if (it.object.get("iconName")) |ic| {
            if (ic == .string) {
                const img = gtk.Image.newFromIconName(dupeZ(ic.string));
                adw.ActionRow.addPrefix(row, img.as(gtk.Widget));
            }
        }
        if (it.object.get("badge")) |bd| {
            if (bd == .string) {
                const lbl = gtk.Label.new(dupeZ(bd.string));
                gtk.Widget.addCssClass(lbl.as(gtk.Widget), "dimmed");
                gtk.Widget.addCssClass(lbl.as(gtk.Widget), "numeric");
                adw.ActionRow.addSuffix(row, lbl.as(gtk.Widget));
            }
        }
        gtk.ListBox.append(box, row.as(gtk.Widget));
    }
}

// ---- event wiring state (installed once by gtk_backend.setEventSink via
// initEvents, BEFORE the NDP socket accepts — so before any widget exists) ----
pub const EmitFn = *const fn (node_id: u32, name: []const u8, payload: protocol.EventPayload) void;
var emit: ?EmitFn = null;
var events_gpa: std.mem.Allocator = undefined;
var events_ready = false;
/// GObject ptr -> the ONE suppressible (change-echo) handler id on it.
var suppress_map: std.AutoHashMapUnmanaged(usize, c_ulong) = .empty;
/// Radio group name -> first CheckButton in the group. Entries are evicted by
/// cbRadioGroupDestroyed when the anchor button dies (a conditionally-rendered
/// radio group unmounts/remounts under the same name — without eviction the
/// next mount joins a freed CheckButton and segfaults in
/// _gtk_check_button_set_group; M13 settings-example crash).
var radio_groups: std.StringHashMapUnmanaged(*gtk.CheckButton) = .empty;

/// Destroy handler for the anchor (first) radio of each group: drop the map
/// entry and its owned key so a later same-named group re-anchors cleanly.
fn cbRadioGroupDestroyed(w: *gtk.Widget, _: ?*anyopaque) callconv(.c) void {
    const dead: *gtk.CheckButton = @ptrCast(@alignCast(w));
    var it = radio_groups.iterator();
    var dead_key: ?[]const u8 = null;
    while (it.next()) |e| {
        if (e.value_ptr.* == dead) {
            dead_key = e.key_ptr.*;
            break;
        }
    }
    if (dead_key) |k| {
        _ = radio_groups.remove(k);
        events_gpa.free(k);
    }
}
/// Outer AdwOverlaySplitView ptr -> pending `listWidth` (M13 three-pane
/// SplitView), read again when the inner split is lazily created (the inner
/// doesn't exist yet at the outer's create time — see ndSplitViewInner).
var split_list_widths: std.AutoHashMapUnmanaged(usize, f64) = .empty;

pub fn initEvents(gpa: std.mem.Allocator, emit_fn: EmitFn) void {
    events_gpa = gpa;
    emit = emit_fn;
    events_ready = true;
}

fn noteSuppressible(obj: *gobject.Object, handler_id: c_ulong) void {
    suppress_map.put(events_gpa, @intFromPtr(obj), handler_id) catch {};
    // Evict on death: the map is keyed by ADDRESS, and GLib recycles those.
    // A stale id belonging to a dead object makes signalHandlerBlock raise a
    // critical and silently fail to block, so a long-lived app that mounts and
    // unmounts controlled text widgets would eventually stop suppressing
    // echoes. Same discipline as cbRadioGroupDestroyed; a weak ref rather than
    // "destroy" because the target can be a GtkTextBuffer, which has none.
    gobject.Object.weakRef(obj, &cbSuppressibleDied, null);
}

fn cbSuppressibleDied(_: ?*anyopaque, dead: *gobject.Object) callconv(.c) void {
    _ = suppress_map.remove(@intFromPtr(dead));
}

fn blockEcho(obj: *gobject.Object) void {
    if (suppress_map.get(@intFromPtr(obj))) |hid| gobject.signalHandlerBlock(obj, hid);
}

fn unblockEcho(obj: *gobject.Object) void {
    if (suppress_map.get(@intFromPtr(obj))) |hid| gobject.signalHandlerUnblock(obj, hid);
}

const MenuRole = enum { none, separator, about, settings, dropped };

fn parseMenuRole(s: []const u8) MenuRole {
    if (std.mem.eql(u8, s, "separator")) return .separator;
    if (std.mem.eql(u8, s, "about")) return .about;
    if (std.mem.eql(u8, s, "settings")) return .settings;
    if (std.mem.eql(u8, s, "none")) return .none;
    return .dropped; // quit/close/minimize/undo/cut/... duplicate window + system chrome (GNOME HIG)
}

