var menu_headerbars: std.ArrayList(*adw.HeaderBar) = .empty;

fn ndAccelKeyName(k: []const u8) []const u8 {
    if (std.mem.eql(u8, k, "enter")) return "Return";
    if (std.mem.eql(u8, k, "escape")) return "Escape";
    if (std.mem.eql(u8, k, "backspace")) return "BackSpace";
    if (std.mem.eql(u8, k, "delete")) return "Delete";
    if (std.mem.eql(u8, k, "space")) return "space";
    if (std.mem.eql(u8, k, "tab")) return "Tab";
    if (std.mem.eql(u8, k, "left")) return "Left";
    if (std.mem.eql(u8, k, "right")) return "Right";
    if (std.mem.eql(u8, k, "up")) return "Up";
    if (std.mem.eql(u8, k, "down")) return "Down";
    if (std.mem.eql(u8, k, "comma")) return "comma";
    if (std.mem.eql(u8, k, "period")) return "period";
    return k; // single printable char (and f1..f12) pass through verbatim
}

fn ndAccelToGtk(spec: []const u8, dupeZ: *const fn ([]const u8) [:0]const u8) ?[:0]const u8 {
    var buf: std.ArrayList(u8) = .empty;
    defer buf.deinit(events_gpa);
    var it = std.mem.splitScalar(u8, spec, '+');
    var key: ?[]const u8 = null;
    while (it.next()) |part| {
        if (std.mem.eql(u8, part, "primary")) buf.appendSlice(events_gpa, "<Primary>") catch return null
        else if (std.mem.eql(u8, part, "shift")) buf.appendSlice(events_gpa, "<Shift>") catch return null
        else if (std.mem.eql(u8, part, "alt")) buf.appendSlice(events_gpa, "<Alt>") catch return null
        else if (std.mem.eql(u8, part, "ctrl")) buf.appendSlice(events_gpa, "<Control>") catch return null
        else key = part;
    }
    const k = key orelse return null;
    buf.appendSlice(events_gpa, ndAccelKeyName(k)) catch return null;
    return dupeZ(buf.items);
}

fn ndMenubarCreate(app: *gtk.Application, window: ?*gtk.Window, defaults: bool) *gtk.Widget {
    menu_app = app;
    menu_window = window;
    const m = gio.Menu.new();
    the_menubar = m;
    menu_defaults = defaults;
    // Native tabs share one scaffold window, so the single primary button must
    // follow the selected tab; onSelectedPage calls back here to re-home it.
    ndtabs_gtk.onTabSelected = &ndMenuRefresh;
    return @ptrCast(@alignCast(m));
}

fn ndMenuCreate(app: *gtk.Application, label: [:0]const u8) *gtk.Widget {
    menu_app = app;
    const m = gio.Menu.new();
    menu_labels.put(events_gpa, @intFromPtr(m), label) catch {};
    return @ptrCast(@alignCast(m));
}

fn ndMenuItemCreate(app: *gtk.Application, props: ?std.json.Value, dupeZ: *const fn ([]const u8) [:0]const u8) *gtk.Widget {
    menu_app = app;
    const item = gio.MenuItem.new(null, null);
    var info = MenuItemInfo{};
    info.label = dupeZ(propStr(props, "label") orelse "");
    if (propStr(props, "iconName")) |ic| info.icon = dupeZ(ic);
    if (propStr(props, "accelerator")) |ac| info.accel = ndAccelToGtk(ac, dupeZ);
    info.role = parseMenuRole(propStr(props, "role") orelse "none");
    info.enabled = propBool(props, "enabled") orelse true;
    menu_item_info.put(events_gpa, @intFromPtr(item), info) catch {};
    return @ptrCast(@alignCast(item));
}

fn cbMenuActionActivate(_: *gobject.Object, _: ?*glib.Variant, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    if (emit) |f| f(node_id, "selected", .{});
}

fn cbMenuAboutActivate(_: *gobject.Object, _: ?*glib.Variant, _: ?*anyopaque) callconv(.c) void {
    const dialog = adw.AboutDialog.new();
    if (menu_window) |w| {
        const title = gtk.Window.getTitle(w);
        if (title) |t| adw.AboutDialog.setApplicationName(dialog, t);
    }
    adw.Dialog.present(dialog.as(adw.Dialog), if (menu_window) |w| w.as(gtk.Widget) else null);
}

fn ndMenuEnsureAbout() void {
    if (menu_about_added) return;
    const app = menu_app orelse return;
    const sa = gio.SimpleAction.new("nd-about", null);
    _ = gobject.signalConnectData(@ptrCast(@alignCast(sa)), "activate", @ptrCast(&cbMenuAboutActivate), null, null, .{});
    gio.ActionMap.addAction(app.as(gio.ActionMap), sa.as(gio.Action));
    menu_about_added = true;
}

pub fn ndMenuItemConnect(item_w: *gtk.Widget, node_id: u32) void {
    const item: *gio.MenuItem = @ptrCast(@alignCast(item_w));
    const info = menu_item_info.getPtr(@intFromPtr(item)) orelse return;
    info.node_id = node_id;
    menu_node_ids.put(events_gpa, node_id, @intFromPtr(item)) catch {};
    if (info.role != .none and info.role != .settings) return;
    const app = menu_app orelse return;
    const name = std.fmt.allocPrintSentinel(events_gpa, "nd-menu-{d}", .{node_id}, 0) catch return;
    const sa = gio.SimpleAction.new(name, null);
    info.action = sa;
    _ = gobject.signalConnectData(@ptrCast(@alignCast(sa)), "activate", @ptrCast(&cbMenuActionActivate), @ptrFromInt(@as(usize, node_id)), null, .{});
    gio.SimpleAction.setEnabled(sa, @intFromBool(info.enabled));
    gio.ActionMap.addAction(app.as(gio.ActionMap), sa.as(gio.Action));
    if (info.accel) |accel| {
        const detailed = std.fmt.allocPrintSentinel(events_gpa, "app.nd-menu-{d}", .{node_id}, 0) catch return;
        var accels = [_]?[*:0]const u8{ accel.ptr, null };
        gtk.Application.setAccelsForAction(app, detailed, @ptrCast(&accels));
    }
}

fn ndMenuItemSetEnabled(item_w: *gtk.Widget, enabled: bool) void {
    const item: *gio.MenuItem = @ptrCast(@alignCast(item_w));
    const info = menu_item_info.getPtr(@intFromPtr(item)) orelse return;
    info.enabled = enabled;
    if (info.action) |sa| gio.SimpleAction.setEnabled(sa, @intFromBool(enabled));
}

/// MenuItem.label / Menu.label updates. A GMenuItem's label is baked into the
/// GMenuModel at build time, so both setters update the registry the builders
/// read and re-run every model that could contain the node (the menubar and
/// any MenuButton/SplitButton owner).
fn ndMenuItemSetLabel(item_w: *gtk.Widget, label: [:0]const u8) void {
    const item: *gio.MenuItem = @ptrCast(@alignCast(item_w));
    const info = menu_item_info.getPtr(@intFromPtr(item)) orelse return;
    if (std.mem.eql(u8, info.label, label)) return;
    info.label = label;
    ndMenuRefresh();
    ndMenuOwnersRefresh();
}

fn ndMenuSetLabel(menu_w: *gtk.Widget, label: [:0]const u8) void {
    const menu: *gio.Menu = @ptrCast(@alignCast(menu_w));
    const key = @intFromPtr(menu);
    if (menu_labels.get(key)) |cur| {
        if (std.mem.eql(u8, cur, label)) return;
    }
    menu_labels.put(events_gpa, key, label) catch return;
    ndMenuRefresh();
    ndMenuOwnersRefresh();
}

fn ndBuildGMenuItem(info: MenuItemInfo) ?*gio.MenuItem {
    switch (info.role) {
        .separator, .dropped => return null,
        .about => {
            const lbl: [*:0]const u8 = if (info.label.len > 0) info.label.ptr else "About";
            return gio.MenuItem.new(lbl, "app.nd-about");
        },
        .none, .settings => {
            const lbl: [*:0]const u8 = if (info.label.len > 0) info.label.ptr else (if (info.role == .settings) "Preferences" else "");
            const detailed = std.fmt.allocPrintSentinel(events_gpa, "app.nd-menu-{d}", .{info.node_id}, 0) catch return null;
            return gio.MenuItem.new(lbl, detailed);
        },
    }
}

/// Generic GMenuModel builder over an ordered MIXED list of menu-node handles
/// — GMenuItem leaves (separators split sections) and nested GMenu submenus.
/// Shared by the menubar's per-menu bodies AND every MenuButton/SplitButton
/// popover (M15 generalization of the previously menubar-only builder); item
/// activation routes through the same app-scoped "app.nd-menu-<node>" actions
/// wherever the model is mounted, so MenuItem's `selected` event keeps
/// working for all owners.
fn ndBuildModelFromList(items: []const usize) ?*gio.Menu {
    const root = gio.Menu.new();
    var section = gio.Menu.new();
    var any = false;
    for (items) |item_ptr| {
        if (menu_item_info.get(item_ptr)) |info| {
            if (info.role == .separator) {
                gio.Menu.appendSection(root, null, section.as(gio.MenuModel));
                section = gio.Menu.new();
                continue;
            }
            if (ndBuildGMenuItem(info)) |gi| {
                gio.Menu.appendItem(section, gi);
                any = true;
            }
        } else if (menu_labels.contains(item_ptr) or submenu_items.contains(item_ptr)) {
            // A <menu> child: nested submenu (menubar menus were previously
            // item-only; buttons commonly mix items and submenus).
            const submenu: *gio.Menu = @ptrFromInt(item_ptr);
            if (ndBuildSubmenuModel(submenu)) |model| {
                const label = menu_labels.get(item_ptr) orelse "";
                const lbl: [*:0]const u8 = if (label.len > 0) label.ptr else "Menu";
                gio.Menu.appendSubmenu(section, lbl, model.as(gio.MenuModel));
                any = true;
            }
        }
    }
    gio.Menu.appendSection(root, null, section.as(gio.MenuModel));
    return if (any) root else null;
}

fn ndBuildSubmenuModel(submenu: *gio.Menu) ?*gio.Menu {
    const items = submenu_items.get(@intFromPtr(submenu)) orelse return null;
    return ndBuildModelFromList(items.items);
}

// ---- M15 menu owners: MenuButton/SplitButton host a GMenuModel built from
// their Menu/MenuItem children — the same node handles the menubar tracks,
// rebuilt per owner on every structural change. Keyed by the owner WIDGET. ----
var menu_owner_children: std.AutoHashMapUnmanaged(usize, std.ArrayList(usize)) = .empty;

fn ndMenuOwnerRebuild(owner: *gtk.Widget) void {
    const children = menu_owner_children.get(@intFromPtr(owner)) orelse return;
    const model = ndBuildModelFromList(children.items);
    const mm: ?*gio.MenuModel = if (model) |m| m.as(gio.MenuModel) else null;
    if (gobject.ext.isA(owner, adw.SplitButton)) {
        adw.SplitButton.setMenuModel(@ptrCast(@alignCast(owner)), mm);
    } else if (gobject.ext.isA(owner, gtk.MenuButton)) {
        gtk.MenuButton.setMenuModel(@ptrCast(@alignCast(owner)), mm);
    }
}

fn ndMenuOwnerAppend(owner: *gtk.Widget, child: *gtk.Widget) void {
    const gop = menu_owner_children.getOrPut(events_gpa, @intFromPtr(owner)) catch return;
    if (!gop.found_existing) gop.value_ptr.* = .empty;
    gop.value_ptr.append(events_gpa, @intFromPtr(child)) catch {};
    ndMenuOwnerRebuild(owner);
}

fn ndMenuOwnerRemove(owner: *gtk.Widget, child: *gtk.Widget) void {
    const list = menu_owner_children.getPtr(@intFromPtr(owner)) orelse return;
    for (list.items, 0..) |c, i| {
        if (c == @intFromPtr(child)) {
            _ = list.orderedRemove(i);
            break;
        }
    }
    ndMenuOwnerRebuild(owner);
}

/// Rebuild every registered button owner — called when a Menu's item list
/// mutates AFTER the Menu was appended to its owner (the owner's set model
/// was built from the old list; GMenu handles aren't live-observed here).
fn ndMenuOwnersRefresh() void {
    var it = menu_owner_children.iterator();
    while (it.next()) |e| ndMenuOwnerRebuild(@ptrFromInt(e.key_ptr.*));
}

/// Destroy handler for MenuButton/SplitButton owners: drop the child list so
/// a GLib address reuse can't resurrect a stale menu (mirrors
/// cbHeaderBarDestroyed's eviction rationale).
fn cbMenuOwnerDestroyed(w: *gtk.Widget, _: ?*anyopaque) callconv(.c) void {
    if (menu_owner_children.fetchRemove(@intFromPtr(w))) |kv| {
        var list = kv.value;
        list.deinit(events_gpa);
    }
}

fn ndBuildMenubarModel() ?*gio.Menu {
    const menubar = the_menubar orelse return null;
    const menus = menubar_menus.get(@intFromPtr(menubar)) orelse return null;
    const root = gio.Menu.new();
    var any = false;
    for (menus.items) |submenu_ptr| {
        const submenu: *gio.Menu = @ptrFromInt(submenu_ptr);
        if (ndBuildSubmenuModel(submenu)) |model| {
            const label = menu_labels.get(submenu_ptr) orelse "";
            const lbl: [*:0]const u8 = if (label.len > 0) label.ptr else "Menu";
            gio.Menu.appendSubmenu(root, lbl, model.as(gio.MenuModel));
            any = true;
        }
    }
    return if (any) root else null;
}

fn ndMenuFindSplit(widget: *gtk.Widget, out: *?*adw.OverlaySplitView) void {
    if (out.* != null) return;
    if (gobject.ext.isA(widget, adw.OverlaySplitView)) {
        out.* = @ptrCast(@alignCast(widget));
        return;
    }
    var child = gtk.Widget.getFirstChild(widget);
    while (child) |c| : (child = gtk.Widget.getNextSibling(c)) {
        ndMenuFindSplit(c, out);
        if (out.* != null) return;
    }
}

fn ndMenuFirstHeaderBar(widget: *gtk.Widget, out: *?*adw.HeaderBar) void {
    if (out.* != null) return;
    if (gobject.ext.isA(widget, adw.HeaderBar)) {
        out.* = @ptrCast(@alignCast(widget));
        return;
    }
    var child = gtk.Widget.getFirstChild(widget);
    while (child) |c| : (child = gtk.Widget.getNextSibling(c)) {
        ndMenuFirstHeaderBar(c, out);
        if (out.* != null) return;
    }
}

/// The AdwHeaderBar of the split layout's innermost CONTENT pane — the header the
/// app declares last, where GNOME homes the primary menu button. Found
/// structurally (drill `getContent` through the nested-split pair), so it is
/// stable no matter what order headerbars were created/remounted in — a re-keyed
/// list/sidebar header re-registering last can no longer hijack the button.
/// Returns null (caller falls back to the last-registered header) when the
/// window is not a split layout.
///
/// The window root is taken from the first ALREADY-ROOTED recorded header, not
/// from the header that triggered this refresh: a remount calls here from the
/// new header's create arm, before it is parented, so its `getRoot` is null —
/// anchoring on it would bail to the fallback and let the remounted header steal
/// the button (the exact folder-switch jump this avoids).
fn ndMenuContentHeaderBar() ?*adw.HeaderBar {
    var root: *gtk.Widget = undefined;
    var found_root = false;
    for (menu_headerbars.items) |hb| {
        if (gtk.Widget.getRoot(hb.as(gtk.Widget))) |r| {
            root = @ptrCast(@alignCast(r));
            found_root = true;
            break;
        }
    }
    if (!found_root) return null;
    // Native tabs: every <window ln> tab is a page in one scaffold window, so a
    // whole-window search pins the button to the first tab's header. Scope the
    // search to the SELECTED page so the button rides whichever tab is visible;
    // a plain window has no tab view and searches the whole root as before.
    const search_root: *gtk.Widget = ndtabs_gtk.selectedTabContent(root) orelse root;
    var split_opt: ?*adw.OverlaySplitView = null;
    ndMenuFindSplit(search_root, &split_opt);
    if (split_opt) |split0| {
        var split = split0;
        var content = adw.OverlaySplitView.getContent(split) orelse return null;
        while (gobject.ext.isA(content, adw.OverlaySplitView)) {
            split = @ptrCast(@alignCast(content));
            content = adw.OverlaySplitView.getContent(split) orelse return null;
        }
        var hb_opt: ?*adw.HeaderBar = null;
        ndMenuFirstHeaderBar(content, &hb_opt);
        return hb_opt;
    }
    // A tab page without a split layout (a plain <toolbarview> tab): the page's
    // own first header. Non-tab windows fall through to the caller's
    // last-registered-header fallback exactly as before.
    if (ndtabs_gtk.selectedTabContent(root)) |page| {
        var hb_opt: ?*adw.HeaderBar = null;
        ndMenuFirstHeaderBar(page, &hb_opt);
        return hb_opt;
    }
    return null;
}

fn ndMenuRefresh() void {
    const app = menu_app orelse return;
    if (the_menubar == null) return;
    ndMenuEnsureAbout();
    const model = ndBuildMenubarModel() orelse return;
    if (menu_headerbars.items.len > 0) {
        const any_hb = menu_headerbars.items[menu_headerbars.items.len - 1];
        const target = ndMenuContentHeaderBar() orelse any_hb;
        if (menu_primary_button == null) {
            const btn = gtk.MenuButton.new();
            // Own a strong ref (sinks the floating ref): rehoming does
            // HeaderBar.remove -> packEnd, and remove() would otherwise drop
            // the last ref and destroy the button mid-rehome (observed as
            // GTK_IS_WIDGET / GTK_IS_MENU_BUTTON criticals with 2+ headerbars).
            _ = gobject.Object.refSink(btn.as(gobject.Object));
            gtk.MenuButton.setIconName(btn, "open-menu-symbolic");
            gtk.Widget.setTooltipText(btn.as(gtk.Widget), "Main Menu");
            menu_primary_button = btn;
        }
        const btn = menu_primary_button.?;
        gtk.MenuButton.setMenuModel(btn, model.as(gio.MenuModel));
        if (menu_primary_parent != target) {
            if (menu_primary_parent) |old| adw.HeaderBar.remove(old, btn.as(gtk.Widget));
            adw.HeaderBar.packEnd(target, btn.as(gtk.Widget));
            menu_primary_parent = target;
        }
    } else {
        gtk.Application.setMenubar(app, model.as(gio.MenuModel));
    }
}

fn ndMenubarAppendMenu(menubar_w: *gtk.Widget, menu_w: *gtk.Widget) void {
    const menubar: *gio.Menu = @ptrCast(@alignCast(menubar_w));
    const gop = menubar_menus.getOrPut(events_gpa, @intFromPtr(menubar)) catch return;
    if (!gop.found_existing) gop.value_ptr.* = .empty;
    gop.value_ptr.append(events_gpa, @intFromPtr(menu_w)) catch {};
    ndMenuRefresh();
}

fn ndMenuAppendItem(menu_w: *gtk.Widget, item_w: *gtk.Widget) void {
    const submenu: *gio.Menu = @ptrCast(@alignCast(menu_w));
    const gop = submenu_items.getOrPut(events_gpa, @intFromPtr(submenu)) catch return;
    if (!gop.found_existing) gop.value_ptr.* = .empty;
    gop.value_ptr.append(events_gpa, @intFromPtr(item_w)) catch {};
    ndMenuRefresh();
    ndMenuOwnersRefresh(); // a button owner holding this Menu re-snapshots it
}

/// GObject weak-ref notify: a recorded headerbar is being finalized (the
/// retained tree holds no ref of its own — structural remove drops the
/// container's only ref, src/tree.zig). Purge every unowned pointer to it
/// BEFORE anything dereferences it: menu_primary_parent outliving its
/// headerbar was a real use-after-free (GPF inside adw_header_bar_remove
/// whenever a keyed <headerbar> remounts, e.g. notes' per-folder list header).
fn ndMenuHeaderBarGone(_: ?*anyopaque, where_the_object_was: *gobject.Object) callconv(.c) void {
    const dead: *adw.HeaderBar = @ptrCast(@alignCast(where_the_object_was)); // identity only — never dereferenced
    var i: usize = 0;
    while (i < menu_headerbars.items.len) {
        if (menu_headerbars.items[i] == dead) {
            _ = menu_headerbars.orderedRemove(i);
        } else i += 1;
    }
    if (menu_primary_parent == dead) {
        // The dying container already unparented the button (widget dispose
        // runs before weak notifies fire); the strong ref taken in
        // ndMenuRefresh keeps the button itself alive for re-homing.
        menu_primary_parent = null;
        if (the_menubar != null) ndMenuRefresh();
    }
}

/// Records a headerbar so a later menubar can home its primary button in the
/// LAST one (GNOME convention: the content pane's header). No-op for menu-less
/// apps beyond the record — the button is only created/moved once a <menubar>
/// exists, so counter/gallery/two-pane trees are behaviorally unchanged.
pub fn ndMenuNoteHeaderBar(hb: *adw.HeaderBar) void {
    menu_headerbars.append(events_gpa, hb) catch {};
    gobject.Object.weakRef(hb.as(gobject.Object), &ndMenuHeaderBarGone, null);
    if (the_menubar != null) ndMenuRefresh();
}

/// Called from the Window structural arm when a non-widget child (the menubar
/// GMenu) is appended: install the primary menu instead of setting it as the
/// window content.
pub fn ndMenuAttachToWindow(_: *gtk.Widget) void {
    ndMenuRefresh();
}

// ---- <headerbar> back/forward navigation (canGoBack/canGoForward +
// onBack/onForward). The GNOME idiom is two flat GtkButtons packed at the
// AdwHeaderBar START (go-previous-symbolic / go-next-symbolic). Buttons
// materialize when either prop is PRESENT (the app opts in) — a header with no
// nav props gets none. `node_id` (for emitting back/forward) arrives via
// ndHeaderBarConnectNav, decoupled from button creation, so any create/connect
// order works: the click callbacks look the id up by AdwHeaderBar pointer. ----
const HeaderBarNav = struct { back: *gtk.Button, forward: *gtk.Button };
var headerbar_navs: std.AutoHashMapUnmanaged(usize, HeaderBarNav) = .empty; // AdwHeaderBar ptr -> buttons
var headerbar_nav_ids: std.AutoHashMapUnmanaged(usize, u32) = .empty; // AdwHeaderBar ptr -> node id

fn cbHeaderBarBack(_: *gtk.Button, data: ?*anyopaque) callconv(.c) void {
    const id = headerbar_nav_ids.get(@intFromPtr(data)) orelse return;
    if (emit) |f| f(id, "back", .{});
}

fn cbHeaderBarForward(_: *gtk.Button, data: ?*anyopaque) callconv(.c) void {
    const id = headerbar_nav_ids.get(@intFromPtr(data)) orelse return;
    if (emit) |f| f(id, "forward", .{});
}

/// Evict a header's nav entries when it is finalized. A `key`-based remount
/// (the settings example re-keys the content header per page) destroys the old
/// AdwHeaderBar and GLib readily reuses its address for the new one; without
/// this the stale entry's dangling button pointers would reach setSensitive.
fn cbHeaderBarDestroyed(w: *gtk.Widget, _: ?*anyopaque) callconv(.c) void {
    const key = @intFromPtr(w);
    _ = headerbar_navs.remove(key);
    _ = headerbar_nav_ids.remove(key);
}

/// Materializes / updates the header's flat back/forward buttons from the
/// canGoBack/canGoForward props (generated HeaderBar create + applyProps arms).
/// The buttons appear on the first call carrying either flag and persist; each
/// flag only drives its own button's `sensitive`, so a one-sided diffed update
/// can't clobber the other (mirrors the AppKit segmented-control behaviour).
pub fn ndHeaderBarApplyNav(hb: *adw.HeaderBar, can_back: ?bool, can_forward: ?bool) void {
    if (can_back == null and can_forward == null) return; // untouched: not a teardown
    const gop = headerbar_navs.getOrPut(events_gpa, @intFromPtr(hb)) catch return;
    if (!gop.found_existing) {
        const back = gtk.Button.new();
        gtk.Button.setIconName(back, "go-previous-symbolic");
        gtk.Widget.addCssClass(back.as(gtk.Widget), "flat");
        const forward = gtk.Button.new();
        gtk.Button.setIconName(forward, "go-next-symbolic");
        gtk.Widget.addCssClass(forward.as(gtk.Widget), "flat");
        _ = gtk.Button.signals.clicked.connect(back, ?*anyopaque, &cbHeaderBarBack, @ptrCast(hb), .{});
        _ = gtk.Button.signals.clicked.connect(forward, ?*anyopaque, &cbHeaderBarForward, @ptrCast(hb), .{});
        adw.HeaderBar.packStart(hb, back.as(gtk.Widget)); // back leftmost, forward to its right
        adw.HeaderBar.packStart(hb, forward.as(gtk.Widget));
        _ = gtk.Widget.signals.destroy.connect(hb.as(gtk.Widget), ?*anyopaque, &cbHeaderBarDestroyed, null, .{});
        gop.value_ptr.* = .{ .back = back, .forward = forward };
    }
    if (can_back) |b| gtk.Widget.setSensitive(gop.value_ptr.back.as(gtk.Widget), @intFromBool(b));
    if (can_forward) |f| gtk.Widget.setSensitive(gop.value_ptr.forward.as(gtk.Widget), @intFromBool(f));
}

/// Records the header's node id so the back/forward click callbacks can emit
/// (generated connectEvents HeaderBar arm). The buttons' click handlers are
/// wired in ndHeaderBarApplyNav; this only supplies the id they look up.
pub fn ndHeaderBarConnectNav(widget: *gtk.Widget, node_id: u32) void {
    headerbar_nav_ids.put(events_gpa, @intFromPtr(widget), node_id) catch {};
}

/// backend.zig routes a non-widget node handle's semantic click here.
/// A menu node's declared enabled state, for the automation a11y probe.
/// Null when the node id names no menu item. Menu handles are GMenuItems, not
/// GtkWidgets, so backend.zig cannot answer this with gtk_widget_is_sensitive.
pub fn menuItemEnabled(node_id: u32) ?bool {
    const item_ptr = menu_node_ids.get(node_id) orelse return null;
    const info = menu_item_info.get(item_ptr) orelse return null;
    return info.enabled;
}

pub fn menuSemanticClick(node_id: u32) bool {
    const item_ptr = menu_node_ids.get(node_id) orelse return false;
    const info = menu_item_info.get(item_ptr) orelse return true;
    switch (info.role) {
        .about => {
            cbMenuAboutActivate(@ptrCast(menu_app orelse return true), null, null);
            return true;
        },
        .separator, .dropped => return true,
        .none, .settings => {
            const app = menu_app orelse return true;
            if (!info.enabled) return true; // disabled: onSelect must not fire
            const name = std.fmt.allocPrintSentinel(events_gpa, "nd-menu-{d}", .{node_id}, 0) catch return true;
            gio.ActionGroup.activateAction(app.as(gio.ActionGroup), name, null);
            return true;
        },
    }
}

const ND_POPOVER_PENDING_OPEN = "nd-popover-pending-open";

/// Cross-cutting structural rule: a GtkPopover child attaches to its tree
/// parent via gtk_widget_set_parent (never box-packed/slotted — GtkPopover is
/// not a layout child). Called from the appendChild/insertBefore guards;
/// honors a create-time open=true that had to wait for a parent to anchor on.
fn ndPopoverAttach(child: *gtk.Widget, parent: *gtk.Widget) void {
    if (!gobject.ext.isA(parent, gtk.Widget)) return; // menu-node parent: nowhere to anchor
    if (gtk.Widget.getParent(child)) |cur| {
        if (cur == parent) return;
        gtk.Widget.unparent(child);
    }
    gtk.Widget.setParent(child, parent);
    if (gobject.Object.getData(asObject(child), ND_POPOVER_PENDING_OPEN) != null) {
        gobject.Object.setData(asObject(child), ND_POPOVER_PENDING_OPEN, null);
        gtk.Popover.popup(@ptrCast(@alignCast(child)));
    }
}

fn ndPositionFromString(s: []const u8) gtk.PositionType {
    if (std.mem.eql(u8, s, "bottom")) return .bottom;
    if (std.mem.eql(u8, s, "left")) return .left;
    if (std.mem.eql(u8, s, "right")) return .right;
    return .top;
}

// ---- LevelIndicator (GtkLevelBar) tier offsets ----
const NdLevelOffsets = struct { warning: ?f64 = null, critical: ?f64 = null };
var level_offsets: std.AutoHashMapUnmanaged(usize, NdLevelOffsets) = .empty;
var level_css_installed = false;

/// Adwaita styles only the stock low/high/full offsets; ND's warning/critical
/// tiers use custom offset names, colored once app-wide from the platform
/// palette (libadwaita's --warning-bg-color / --error-bg-color variables).
fn ndLevelBarEnsureCss(bar: *gtk.LevelBar) void {
    if (level_css_installed) return;
    level_css_installed = true;
    const provider = gtk.CssProvider.new();
    gtk.CssProvider.loadFromString(provider, "levelbar block.warning { background-color: var(--warning-bg-color); } levelbar block.error { background-color: var(--error-bg-color); }");
    gtk.StyleContext.addProviderForDisplay(gtk.Widget.getDisplay(bar.as(gtk.Widget)), provider.as(gtk.StyleProvider), 600); // STYLE_PROVIDER_PRIORITY_APPLICATION
}

fn cbLevelBarDestroyed(w: *gtk.Widget, _: ?*anyopaque) callconv(.c) void {
    _ = level_offsets.remove(@intFromPtr(w));
}

/// Rising-is-worse tiers (NSLevelIndicator capacity semantics): value at or
/// below warningValue keeps the plain accent fill; above it .warning; above
/// criticalValue .error. GtkLevelBar offsets bracket DOWNWARD (an offset
/// styles the interval it tops), so the tiers translate to: nd-ok topped at
/// warning, warning topped at critical, error topped at max. A null param
/// leaves that threshold as previously applied (diffed prop updates carry
/// only the changed key — same merge ndHeaderBarApplyNav does).
fn ndLevelBarApplyOffsets(bar: *gtk.LevelBar, warning: ?f64, critical: ?f64) void {
    if (warning == null and critical == null) return;
    const gop = level_offsets.getOrPut(events_gpa, @intFromPtr(bar)) catch return;
    if (!gop.found_existing) {
        gop.value_ptr.* = .{};
        _ = gtk.Widget.signals.destroy.connect(bar.as(gtk.Widget), ?*anyopaque, &cbLevelBarDestroyed, null, .{});
    }
    if (warning) |w| gop.value_ptr.warning = w;
    if (critical) |c| gop.value_ptr.critical = c;
    ndLevelBarEnsureCss(bar);
    // Drop the stock offsets so their bracket classes can't fight ND's tiers,
    // then re-add ND's from the merged state (add-with-same-name replaces).
    gtk.LevelBar.removeOffsetValue(bar, "low");
    gtk.LevelBar.removeOffsetValue(bar, "high");
    gtk.LevelBar.removeOffsetValue(bar, "full");
    gtk.LevelBar.removeOffsetValue(bar, "nd-ok");
    gtk.LevelBar.removeOffsetValue(bar, "warning");
    gtk.LevelBar.removeOffsetValue(bar, "error");
    const max = gtk.LevelBar.getMaxValue(bar);
    if (gop.value_ptr.warning) |w| {
        gtk.LevelBar.addOffsetValue(bar, "nd-ok", w);
        gtk.LevelBar.addOffsetValue(bar, "warning", gop.value_ptr.critical orelse max);
        if (gop.value_ptr.critical != null) gtk.LevelBar.addOffsetValue(bar, "error", max);
    } else if (gop.value_ptr.critical) |c| {
        gtk.LevelBar.addOffsetValue(bar, "nd-ok", c);
        gtk.LevelBar.addOffsetValue(bar, "error", max);
    }
}

// ---- ColorPicker (GtkColorDialogButton) hex round-trip ----

/// #rrggbb / #rrggbbaa formatter for the wire value (style.zig's color
/// convention). The alpha byte is included only when not fully opaque.
fn ndRgbaToHex(rgba: *const gdk.RGBA, buf: []u8) []const u8 {
    const r: u32 = @intFromFloat(@round(std.math.clamp(@as(f64, rgba.f_red), 0, 1) * 255.0));
    const g: u32 = @intFromFloat(@round(std.math.clamp(@as(f64, rgba.f_green), 0, 1) * 255.0));
    const b: u32 = @intFromFloat(@round(std.math.clamp(@as(f64, rgba.f_blue), 0, 1) * 255.0));
    const a: u32 = @intFromFloat(@round(std.math.clamp(@as(f64, rgba.f_alpha), 0, 1) * 255.0));
    if (a == 255) return std.fmt.bufPrint(buf, "#{x:0>2}{x:0>2}{x:0>2}", .{ r, g, b }) catch "#000000";
    return std.fmt.bufPrint(buf, "#{x:0>2}{x:0>2}{x:0>2}{x:0>2}", .{ r, g, b, a }) catch "#000000";
}

fn ndRgbaClose(a: *const gdk.RGBA, b: *const gdk.RGBA) bool {
    const eps: f32 = 1.0 / 255.0;
    return @abs(a.f_red - b.f_red) < eps and @abs(a.f_green - b.f_green) < eps and @abs(a.f_blue - b.f_blue) < eps and @abs(a.f_alpha - b.f_alpha) < eps;
}

// ---- DatePicker (GtkCalendar) ISO round-trip + min/max clamp state ----
const NdDateLimits = struct { min: ?i64 = null, max: ?i64 = null };
var calendar_limits: std.AutoHashMapUnmanaged(usize, NdDateLimits) = .empty;

fn cbCalendarDestroyed(w: *gtk.Widget, _: ?*anyopaque) callconv(.c) void {
    _ = calendar_limits.remove(@intFromPtr(w));
}

/// ISO YYYY-MM-DD -> comparable key y*10000 + m*100 + d, or null if malformed.
fn ndDateKeyFromIso(s: []const u8) ?i64 {
    if (s.len != 10 or s[4] != '-' or s[7] != '-') return null;
    const y = std.fmt.parseInt(i64, s[0..4], 10) catch return null;
    const m = std.fmt.parseInt(i64, s[5..7], 10) catch return null;
    const d = std.fmt.parseInt(i64, s[8..10], 10) catch return null;
    if (m < 1 or m > 12 or d < 1 or d > 31) return null;
    return y * 10000 + m * 100 + d;
}

fn ndCalendarDateKey(cal: *gtk.Calendar) i64 {
    const dt = gtk.Calendar.getDate(cal); // transfer full
    defer glib.DateTime.unref(dt);
    const y: i64 = @intCast(glib.DateTime.getYear(dt));
    const m: i64 = @intCast(glib.DateTime.getMonth(dt));
    const d: i64 = @intCast(glib.DateTime.getDayOfMonth(dt));
    return y * 10000 + m * 100 + d;
}

/// GTK 4.20+ deprecated the int day/month/year props; select_day with a
/// GDateTime is the supported `date` surface (design brief 2026-07).
fn ndCalendarSelectKey(cal: *gtk.Calendar, key: i64) void {
    const dt = glib.DateTime.newLocal(@intCast(@divTrunc(key, 10000)), @intCast(@mod(@divTrunc(key, 100), 100)), @intCast(@mod(key, 100)), 0, 0, 0) orelse return;
    defer glib.DateTime.unref(dt);
    gtk.Calendar.selectDay(cal, dt);
}

fn ndIsoFromKey(key: i64, buf: []u8) []const u8 {
    const y: u64 = @intCast(@divTrunc(key, 10000));
    const m: u64 = @intCast(@mod(@divTrunc(key, 100), 100));
    const d: u64 = @intCast(@mod(key, 100));
    return std.fmt.bufPrint(buf, "{d:0>4}-{d:0>2}-{d:0>2}", .{ y, m, d }) catch "";
}

/// minDate/maxDate merge (diffed updates carry only the changed key); the
/// empty string clears a bound. Enforcement lives in cbCalendarDaySelected —
/// GtkCalendar has no native range clamp.
fn ndCalendarSetLimits(cal: *gtk.Calendar, min_s: ?[]const u8, max_s: ?[]const u8) void {
    if (min_s == null and max_s == null) return;
    const gop = calendar_limits.getOrPut(events_gpa, @intFromPtr(cal)) catch return;
    if (!gop.found_existing) {
        gop.value_ptr.* = .{};
        _ = gtk.Widget.signals.destroy.connect(cal.as(gtk.Widget), ?*anyopaque, &cbCalendarDestroyed, null, .{});
    }
    if (min_s) |s| gop.value_ptr.min = if (s.len == 0) null else ndDateKeyFromIso(s);
    if (max_s) |s| gop.value_ptr.max = if (s.len == 0) null else ndDateKeyFromIso(s);
}

// ---- Video (GtkVideo) media-module detection + src routing ----
var video_media_checked = false;
var video_media_available = false;

/// GtkMediaFile's real backend ships separately on some distros
/// (gtk4-media-gstreamer & co.); with none installed GTK falls back to its
/// no-op "GtkNoMediaFile" implementation (plus GTK's own one-time warning).
fn ndVideoMediaAvailable() bool {
    if (video_media_checked) return video_media_available;
    video_media_checked = true;
    const mf = gtk.MediaFile.new();
    defer gobject.Object.unref(asObject(mf));
    const instance: *gobject.TypeInstance = @ptrCast(@alignCast(mf));
    const type_name = std.mem.span(gobject.typeNameFromInstance(instance));
    video_media_available = !std.mem.eql(u8, type_name, "GtkNoMediaFile");
    return video_media_available;
}

/// GFile wraps both plain paths and URIs (there is no gtk_video_new_for_uri).
fn ndVideoSetSrc(video: *gtk.Video, src: [:0]const u8) void {
    if (src.len == 0) {
        gtk.Video.setFile(video, null);
        return;
    }
    const file = if (std.mem.indexOf(u8, src, "://") != null) gio.File.newForUri(src) else gio.File.newForPath(src);
    gtk.Video.setFile(video, file); // property setter refs; drop ours
    gobject.Object.unref(@ptrCast(@alignCast(file)));
}

// ---- cmux-parity-polish-2: Paned (draggable two-child split, distinct from
// SplitView's collapsible-sidebar AdwOverlaySplitView) ----
const ND_PANED_PENDING_FRACTION = "nd-paned-pending-fraction";
const ND_PANED_TICK_ID = "nd-paned-tick-id";
const ND_PANED_DEBOUNCE_ID = "nd-paned-debounce-id";
const ND_PANED_NODE_ID = "nd-paned-node-id";

/// `position` is a 0..1 fraction of the total size, but GtkPaned's own
/// `position` property is a pixel offset from the left/top — converting
/// needs the widget's current allocation, which is 0 until the first layout
/// pass. Applied immediately once allocated (the update path); otherwise
/// stashed for the first-layout tick retry (cbPanedMapped/ndPanedTickApply)
/// to replay once real geometry exists.
fn ndPanedApplyPosition(paned: *gtk.Paned, frac: f64) void {
    const widget = paned.as(gtk.Widget);
    const horizontal = gtk.Orientable.getOrientation(paned.as(gtk.Orientable)) == .horizontal;
    const total = if (horizontal) gtk.Widget.getAllocatedWidth(widget) else gtk.Widget.getAllocatedHeight(widget);
    if (total <= 0) {
        // +1: a bit-cast 0.0 fraction is the null pointer, which qdata can't
        // tell apart from "no data set" — offset by one, undo it on read.
        gobject.Object.setData(asObject(widget), ND_PANED_PENDING_FRACTION, @ptrFromInt(@as(usize, @bitCast(frac)) + 1));
        // An already-mapped widget gets no further "map", so kick the retry here.
        if (gtk.Widget.getMapped(widget) != 0) ndPanedEnsureTick(widget);
        return;
    }
    blockEcho(asObject(widget));
    gtk.Paned.setPosition(paned, @intFromFloat(@round(frac * @as(f64, @floatFromInt(total)))));
    unblockEcho(asObject(widget));
}

/// GTK4 emits "map" BEFORE the first size-allocate, so the allocation is
/// still 0 here and the stashed fraction can't be converted yet. Start a
/// per-frame tick retry instead of applying directly.
fn cbPanedMapped(obj: *gobject.Object, _: ?*anyopaque) callconv(.c) void {
    if (gobject.Object.getData(obj, ND_PANED_PENDING_FRACTION) == null) return;
    ndPanedEnsureTick(@ptrCast(@alignCast(obj)));
}

fn ndPanedEnsureTick(widget: *gtk.Widget) void {
    const obj = asObject(widget);
    if (gobject.Object.getData(obj, ND_PANED_TICK_ID) != null) return;
    const id = gtk.Widget.addTickCallback(widget, &ndPanedTickApply, null, null);
    gobject.Object.setData(obj, ND_PANED_TICK_ID, @ptrFromInt(@as(usize, id))); // tick ids start at 1
}

/// Applies the stashed fraction on the first frame with a real allocation,
/// then removes itself. GTK drops live tick callbacks when the widget is
/// destroyed, so no extra teardown bookkeeping is needed.
fn ndPanedTickApply(widget: *gtk.Widget, _: *gdk.FrameClock, _: ?*anyopaque) callconv(.c) c_int {
    const obj = asObject(widget);
    const raw = gobject.Object.getData(obj, ND_PANED_PENDING_FRACTION) orelse {
        gobject.Object.setData(obj, ND_PANED_TICK_ID, null);
        return 0; // G_SOURCE_REMOVE: the update path applied it meanwhile
    };
    const paned: *gtk.Paned = @ptrCast(@alignCast(widget));
    const horizontal = gtk.Orientable.getOrientation(paned.as(gtk.Orientable)) == .horizontal;
    const total = if (horizontal) gtk.Widget.getAllocatedWidth(widget) else gtk.Widget.getAllocatedHeight(widget);
    if (total <= 0) return 1; // G_SOURCE_CONTINUE: not laid out yet
    gobject.Object.setData(obj, ND_PANED_PENDING_FRACTION, null);
    gobject.Object.setData(obj, ND_PANED_TICK_ID, null);
    const frac: f64 = @bitCast(@as(usize, @intFromPtr(raw)) - 1); // undo the +1 offset from setData
    ndPanedApplyPosition(paned, frac);
    return 0; // G_SOURCE_REMOVE
}

/// Fired 150ms after the last notify::position (cbPanedPositionChanged's
/// debounce) — reads the settled divider position back as a 0..1 fraction
/// and emits onPositionChanged. `user_data` holds the ref cbPanedPositionChanged
/// took to keep the widget alive across the wait; always released here.
fn ndPanedEmitPosition(user_data: ?*anyopaque) callconv(.c) c_int {
    const obj: *gobject.Object = @ptrCast(@alignCast(user_data.?));
    defer gobject.Object.unref(obj);
    gobject.Object.setData(obj, ND_PANED_DEBOUNCE_ID, null);
    const node_raw = gobject.Object.getData(obj, ND_PANED_NODE_ID) orelse return 0;
    const node_id: u32 = @intCast(@intFromPtr(node_raw));
    const paned: *gtk.Paned = @ptrCast(@alignCast(obj));
    const widget = paned.as(gtk.Widget);
    const horizontal = gtk.Orientable.getOrientation(paned.as(gtk.Orientable)) == .horizontal;
    const total = if (horizontal) gtk.Widget.getAllocatedWidth(widget) else gtk.Widget.getAllocatedHeight(widget);
    if (total <= 0) return 0; // G_SOURCE_REMOVE
    const frac = @as(f64, @floatFromInt(gtk.Paned.getPosition(paned))) / @as(f64, @floatFromInt(total));
    if (emit) |f| f(node_id, "positionChanged", .{ .position = frac });
    return 0; // G_SOURCE_REMOVE
}

/// Cross-cutting removal hook (AppKit peer: ndPanedTeardown in
/// PanedController.swift): a removed `<paned>`'s pending 150ms settle timer
/// (cbPanedPositionChanged) would otherwise outlive the widget's place in
/// the tree and fire against stale geometry. Cancels it and drops the ref
/// the timer held. No-op for every other widget kind.
pub fn ndPanedStructuralTeardown(child: *gtk.Widget) void {
    if (!gobject.ext.isA(child, gtk.Paned)) return;
    const obj = asObject(child);
    const raw = gobject.Object.getData(obj, ND_PANED_DEBOUNCE_ID) orelse return;
    _ = glib.Source.remove(@intCast(@intFromPtr(raw)));
    gobject.Object.setData(obj, ND_PANED_DEBOUNCE_ID, null);
    gobject.Object.unref(obj); // the cancelled timer's ref
}

// ---- HIG-gap wave: ToolbarView bar styles, HeaderBar subtitle, TabView
// view-stack access, SplitView adaptive breakpoint ----

fn ndToolbarStyleFromString(s: []const u8) adw.ToolbarStyle {
    if (std.mem.eql(u8, s, "raised")) return .raised;
    if (std.mem.eql(u8, s, "raised-border")) return .raised_border;
    return .flat;
}

/// Subtitle update on a live header. A header created with neither title nor
/// subtitle has no AdwWindowTitle — build one on the first non-empty subtitle.
fn ndHeaderBarSetSubtitle(hb: *adw.HeaderBar, subtitle: [:0]const u8) void {
    if (adw.HeaderBar.getTitleWidget(hb)) |tw| {
        if (gobject.ext.isA(tw, adw.WindowTitle)) {
            adw.WindowTitle.setSubtitle(@ptrCast(@alignCast(tw)), subtitle);
            return;
        }
    }
    if (subtitle.len == 0) return;
    const wt = adw.WindowTitle.new("", subtitle);
    adw.HeaderBar.setTitleWidget(hb, wt.as(gtk.Widget));
    adw.HeaderBar.setShowTitle(hb, 1);
}

/// Title update on a live header, the peer of ndHeaderBarSetSubtitle. A
/// header whose title slot holds a SearchInput (headerBarAttach's address-bar
/// shape) keeps it: only an AdwWindowTitle is ever retargeted, and a fresh one
/// is built only when the slot is empty.
fn ndHeaderBarSetTitle(hb: *adw.HeaderBar, title: [:0]const u8) void {
    if (adw.HeaderBar.getTitleWidget(hb)) |tw| {
        if (gobject.ext.isA(tw, adw.WindowTitle)) {
            adw.WindowTitle.setTitle(@ptrCast(@alignCast(tw)), title);
        }
        return;
    }
    if (title.len == 0) return;
    const wt = adw.WindowTitle.new(title, "");
    adw.HeaderBar.setTitleWidget(hb, wt.as(gtk.Widget));
    adw.HeaderBar.setShowTitle(hb, 1);
}

/// The AdwViewStack inside a TabView's wrapping box (switcher scroller above,
/// stack below — see the TabView create arm).
fn ndTabViewStack(widget: *gtk.Widget) ?*adw.ViewStack {
    var child = gtk.Widget.getFirstChild(widget);
    while (child) |c| : (child = gtk.Widget.getNextSibling(c)) {
        if (gobject.ext.isA(c, adw.ViewStack)) return @ptrCast(@alignCast(c));
    }
    return null;
}

/// The GtkScrolledWindow holding a TabView's switcher. The switcher scrolls
/// rather than ellipsizes, which is what keeps a sixteen-page TabView legible.
fn ndTabViewSwitcherScroller(widget: *gtk.Widget) ?*gtk.ScrolledWindow {
    var child = gtk.Widget.getFirstChild(widget);
    while (child) |c| : (child = gtk.Widget.getNextSibling(c)) {
        if (gobject.ext.isA(c, gtk.ScrolledWindow)) return @ptrCast(@alignCast(c));
    }
    return null;
}

/// Upgrades a TabView's switcher to AdwViewSwitcher the first time one of its
/// pages declares an icon. A TabView starts with an AdwInlineViewSwitcher in
/// labels mode because AdwViewSwitcher renders the missing-image fallback in
/// every icon-less button's icon slot, and pages attach after create so the
/// choice cannot be made there.
fn ndTabViewEnsureIconSwitcher(widget: *gtk.Widget, stack: *adw.ViewStack) void {
    const scroller = ndTabViewSwitcherScroller(widget) orelse return;
    const cur = gtk.ScrolledWindow.getChild(scroller) orelse return;
    if (gobject.ext.isA(cur, adw.ViewSwitcher)) return;
    const switcher = adw.ViewSwitcher.new();
    adw.ViewSwitcher.setStack(switcher, stack);
    adw.ViewSwitcher.setPolicy(switcher, .wide);
    gtk.ScrolledWindow.setChild(scroller, switcher.as(gtk.Widget));
}

const ND_SPLIT_PENDING_BREAKPOINT = "nd-split-pending-breakpoint";

/// Installs the stashed `breakpoint` px value as an AdwBreakpoint on the
/// SplitView's AdwApplicationWindow ancestor at first map — the window does
/// not exist at SplitView create (same pending-qdata + map shape as
/// ND_PANED_PENDING_FRACTION; an int px never needs the +1 float trick since
/// 0 means "off" and is never stashed). The breakpoint's setter flips this
/// split view's `collapsed` below max-width: Npx; apps that also want the
/// signal listen for their own state via the collapsed prop round-trip.
fn cbSplitViewMapped(obj: *gobject.Object, _: ?*anyopaque) callconv(.c) void {
    const raw = gobject.Object.getData(obj, ND_SPLIT_PENDING_BREAKPOINT) orelse return;
    gobject.Object.setData(obj, ND_SPLIT_PENDING_BREAKPOINT, null);
    const px: f64 = @floatFromInt(@as(usize, @intFromPtr(raw)));
    const widget: *gtk.Widget = @ptrCast(@alignCast(obj));
    const root = gtk.Widget.getRoot(widget) orelse return;
    if (!gobject.ext.isA(root, adw.ApplicationWindow)) return;
    const win: *adw.ApplicationWindow = @ptrCast(@alignCast(root));
    const cond = adw.BreakpointCondition.newLength(.max_width, px, .px);
    const bp = adw.Breakpoint.new(cond); // takes ownership of cond
    var v = gobject.ext.Value.newFrom(true);
    defer gobject.Value.unset(&v);
    adw.Breakpoint.addSetter(bp, obj, "collapsed", &v);
    adw.ApplicationWindow.addBreakpoint(win, bp); // takes ownership of bp
}

const nd_variant_classes = [_][:0]const u8{ "accent", "success", "warning", "error" };

/// Badge/Tag `variant`. libadwaita already ships accent/success/warning/error
/// as color classes, and the capsule fill in src/gtk/basecss.zig is
/// alpha(currentColor, 0.12), so recoloring the text tints the pill with it.
/// `neutral` is the bare capsule.
fn ndApplyVariant(widget: *gtk.Widget, variant: []const u8) void {
    for (nd_variant_classes) |c| {
        if (std.mem.eql(u8, variant, c)) gtk.Widget.addCssClass(widget, c) else gtk.Widget.removeCssClass(widget, c);
    }
}

const ND_BADGE_DOT = "nd-badge-dot";

/// `<badge>`: a GtkLabel wearing basecss.zig's `.nd-badge` capsule, or a bare
/// bullet glyph in dot mode (a capsule with no text would still carry the
/// class's horizontal padding).
fn ndBadgeCreate(text: [:0]const u8, dot: bool, variant: []const u8) *gtk.Widget {
    const label = if (dot) gtk.Label.new("●") else gtk.Label.new(text);
    const w = label.as(gtk.Widget);
    if (dot) gobject.Object.setData(asObject(w), ND_BADGE_DOT, @ptrFromInt(1)) else gtk.Widget.addCssClass(w, "nd-badge");
    ndApplyVariant(w, variant);
    return w;
}

fn ndBadgeSetLabel(widget: *gtk.Widget, text: [:0]const u8) void {
    if (gobject.Object.getData(asObject(widget), ND_BADGE_DOT) != null) return; // dot badges carry no text
    gtk.Label.setText(@ptrCast(@alignCast(widget)), text);
}

const ND_TAG_NODE_ID = "nd-tag-node-id";

/// `<tag>` is always a GtkBox so the removable and plain shapes share one
/// handle type: a `.pill` GtkLabel (capsule from basecss.zig) plus, when
/// removable, a flat circular close button.
fn ndTagCreate(text: [:0]const u8, variant: []const u8, removable: bool) *gtk.Widget {
    const box = gtk.Box.new(.horizontal, 2);
    const label = gtk.Label.new(text);
    gtk.Widget.addCssClass(label.as(gtk.Widget), "pill");
    ndApplyVariant(label.as(gtk.Widget), variant);
    gtk.Box.append(box, label.as(gtk.Widget));
    if (removable) {
        const btn = gtk.Button.newFromIconName("window-close-symbolic");
        gtk.Widget.addCssClass(btn.as(gtk.Widget), "flat");
        gtk.Widget.addCssClass(btn.as(gtk.Widget), "circular");
        gtk.Widget.setValign(btn.as(gtk.Widget), .center);
        _ = gobject.signalConnectData(asObject(btn), "clicked", @ptrCast(&cbTagRemoveClicked), null, null, .{});
        gtk.Box.append(box, btn.as(gtk.Widget));
    }
    gtk.Widget.setHalign(box.as(gtk.Widget), .start);
    return box.as(gtk.Widget);
}

/// The node id lives on the box (recorded by connectEvents), not on the close
/// button, so the button can be built before the id is known.
fn cbTagRemoveClicked(obj: *gobject.Object, _: ?*anyopaque) callconv(.c) void {
    const btn: *gtk.Widget = @ptrCast(@alignCast(obj));
    const box = gtk.Widget.getParent(btn) orelse return;
    const raw = gobject.Object.getData(asObject(box), ND_TAG_NODE_ID) orelse return;
    const node_id: u32 = @intCast(@intFromPtr(raw));
    if (emit) |f| f(node_id, "removed", .{});
}

fn ndTagConnect(widget: *gtk.Widget, node_id: u32) void {
    gobject.Object.setData(asObject(widget), ND_TAG_NODE_ID, @ptrFromInt(@as(usize, node_id)));
}

fn ndTagLabel(widget: *gtk.Widget) ?*gtk.Label {
    const first = gtk.Widget.getFirstChild(widget) orelse return null;
    if (!gobject.ext.isA(first, gtk.Label)) return null;
    return @ptrCast(@alignCast(first));
}

/// `<kbd>` is a GtkFrame (Adwaita draws it as a 1px rounded border, which is
/// the keycap) around a monospace caption label. The margins are what keep the
/// glyphs off that border; a frame has no padding of its own.
fn ndKbdCreate(keys: [:0]const u8) *gtk.Widget {
    const frame = gtk.Frame.new(null);
    const label = gtk.Label.new(keys);
    const lw = label.as(gtk.Widget);
    gtk.Widget.addCssClass(lw, "monospace");
    gtk.Widget.addCssClass(lw, "caption");
    gtk.Widget.setMarginStart(lw, 6);
    gtk.Widget.setMarginEnd(lw, 6);
    gtk.Widget.setMarginTop(lw, 1);
    gtk.Widget.setMarginBottom(lw, 1);
    gtk.Frame.setChild(frame, lw);
    gtk.Widget.setValign(frame.as(gtk.Widget), .center);
    gtk.Widget.setHalign(frame.as(gtk.Widget), .start);
    return frame.as(gtk.Widget);
}

fn ndKbdLabel(widget: *gtk.Widget) ?*gtk.Label {
    const child = gtk.Frame.getChild(@ptrCast(@alignCast(widget))) orelse return null;
    return @ptrCast(@alignCast(child));
}

/// GtkDropDown's search needs an expression to match rows against; a
/// GtkStringList's rows expose their text as GtkStringObject's "string".
fn ndDropDownSearchExpression() *gtk.Expression {
    return gtk.PropertyExpression.new(gtk.StringObject.getGObjectType(), null, "string").as(gtk.Expression);
}

/// ComboBox `text`. GtkDropDown has no free-text entry, so the typed value is
/// resolved against the option list: an exact match selects that row, anything
/// else leaves the selection alone.
fn ndDropDownSelectText(dd: *gtk.DropDown, text: []const u8) void {
    const model = gtk.DropDown.getModel(dd) orelse return;
    const sl: *gtk.StringList = @ptrCast(@alignCast(model));
    const n = gio.ListModel.getNItems(model);
    var i: c_uint = 0;
    while (i < n) : (i += 1) {
        const s = gtk.StringList.getString(sl, i) orelse continue;
        if (std.mem.eql(u8, std.mem.span(s), text)) {
            if (gtk.DropDown.getSelected(dd) != i) gtk.DropDown.setSelected(dd, i);
            return;
        }
    }
}

fn ndDropDownSelectedText(dd: *gtk.DropDown) ?[]const u8 {
    const item = gtk.DropDown.getSelectedItem(dd) orelse return null;
    const so: *gtk.StringObject = @ptrCast(@alignCast(item));
    return std.mem.span(gtk.StringObject.getString(so));
}

const ND_CRUMB_NODE_ID = "nd-crumb-node-id";
const ND_CRUMB_INDEX = "nd-crumb-index";
const ND_CRUMB_SELECTED = "nd-crumb-selected";

/// `<breadcrumb>` is a GtkBox rebuilt whenever `items` change: one flat
/// GtkButton per crumb with a dimmed separator label between them. The node id
/// lives on the box and the crumb index on each button, so a rebuild long
/// after connectEvents still emits the right pair.
fn ndBreadcrumbRebuild(widget: *gtk.Widget, items: ?std.json.Array, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    // Absent key = untouched: an update carrying only `selectedIndex` must not
    // wipe the crumbs on its way past.
    const arr = items orelse return;
    const box: *gtk.Box = @ptrCast(@alignCast(widget));
    while (gtk.Widget.getFirstChild(widget)) |child| gtk.Box.remove(box, child);
    const selected = ndBreadcrumbSelected(widget);
    var i: usize = 0;
    for (arr.items) |item| {
        if (item != .string) continue;
        if (i > 0) {
            const sep = gtk.Label.new("›");
            gtk.Widget.addCssClass(sep.as(gtk.Widget), "dimmed");
            gtk.Box.append(box, sep.as(gtk.Widget));
        }
        const btn = gtk.Button.newWithLabel(dupeZ(item.string));
        gtk.Widget.addCssClass(btn.as(gtk.Widget), "flat");
        if (@as(i64, @intCast(i)) == selected) gtk.Widget.addCssClass(btn.as(gtk.Widget), "heading");
        gobject.Object.setData(asObject(btn), ND_CRUMB_INDEX, @ptrFromInt(i + 1)); // +1: slot 0 is indistinguishable from unset
        _ = gobject.signalConnectData(asObject(btn), "clicked", @ptrCast(&cbCrumbClicked), null, null, .{});
        gtk.Box.append(box, btn.as(gtk.Widget));
        i += 1;
    }
}

/// An update carries only the keys that changed, so the current crumb index
/// is kept on the box: an `items` rebuild has to re-apply it, and a
/// `selectedIndex` update only moves the emphasis class.
fn ndBreadcrumbSelected(widget: *gtk.Widget) i64 {
    const raw = gobject.Object.getData(asObject(widget), ND_CRUMB_SELECTED) orelse return -1;
    return @as(i64, @intCast(@intFromPtr(raw))) - 1;
}

fn ndBreadcrumbSetSelected(widget: *gtk.Widget, selected: i64) void {
    const slot: usize = if (selected < 0) 0 else @intCast(selected + 1);
    gobject.Object.setData(asObject(widget), ND_CRUMB_SELECTED, @ptrFromInt(slot));
    var child = gtk.Widget.getFirstChild(widget);
    while (child) |c| : (child = gtk.Widget.getNextSibling(c)) {
        const raw_idx = gobject.Object.getData(asObject(c), ND_CRUMB_INDEX) orelse continue;
        const idx: i64 = @intCast(@intFromPtr(raw_idx) - 1);
        if (idx == selected) gtk.Widget.addCssClass(c, "heading") else gtk.Widget.removeCssClass(c, "heading");
    }
}

fn cbCrumbClicked(obj: *gobject.Object, _: ?*anyopaque) callconv(.c) void {
    const btn: *gtk.Widget = @ptrCast(@alignCast(obj));
    const box = gtk.Widget.getParent(btn) orelse return;
    const raw_id = gobject.Object.getData(asObject(box), ND_CRUMB_NODE_ID) orelse return;
    const raw_idx = gobject.Object.getData(obj, ND_CRUMB_INDEX) orelse return;
    const node_id: u32 = @intCast(@intFromPtr(raw_id));
    const idx: i64 = @intCast(@intFromPtr(raw_idx) - 1);
    if (emit) |f| f(node_id, "itemActivated", .{ .index = idx });
}

fn ndBreadcrumbConnect(widget: *gtk.Widget, node_id: u32) void {
    gobject.Object.setData(asObject(widget), ND_CRUMB_NODE_ID, @ptrFromInt(@as(usize, node_id)));
}

const ND_RATING_STARS = "nd-rating-stars";

/// LevelIndicator `indicatorStyle="rating"`. GTK has no rating level bar, so
/// the widget becomes a row of star icons rebuilt on every value change; the
/// star count is the schema `max`, stashed on the box because an update only
/// carries `value`.
fn ndRatingCreate(max: f64, value: f64) *gtk.Widget {
    const box = gtk.Box.new(.horizontal, 2);
    const stars: usize = if (max >= 1) @intFromFloat(@round(max)) else 5;
    gobject.Object.setData(asObject(box), ND_RATING_STARS, @ptrFromInt(stars));
    gtk.Widget.setHalign(box.as(gtk.Widget), .start);
    ndRatingRebuild(box.as(gtk.Widget), value);
    return box.as(gtk.Widget);
}

fn ndRatingRebuild(widget: *gtk.Widget, value: f64) void {
    const box: *gtk.Box = @ptrCast(@alignCast(widget));
    const raw = gobject.Object.getData(asObject(widget), ND_RATING_STARS) orelse return;
    const stars: usize = @intFromPtr(raw);
    while (gtk.Widget.getFirstChild(widget)) |child| gtk.Box.remove(box, child);
    var i: usize = 0;
    while (i < stars) : (i += 1) {
        const filled = @as(f64, @floatFromInt(i)) < value;
        const img = gtk.Image.newFromIconName(if (filled) "starred-symbolic" else "non-starred-symbolic");
        gtk.Box.append(box, img.as(gtk.Widget));
    }
}

/// ComboBox wires BOTH its events off one `notify::selected` handler: the
/// echo-suppression map holds one handler id per object, so two connections
/// would leave the second unblockable during a React-driven update.
fn ndComboBoxConnect(widget: *gtk.Widget, node_id: u32) void {
    const data: ?*anyopaque = @ptrFromInt(@as(usize, node_id));
    const hid = gobject.signalConnectData(asObject(widget), "notify::selected", @ptrCast(&cbComboBoxSelected), data, null, .{});
    noteSuppressible(asObject(widget), hid);
}

// notify:: handlers get (object, pspec, user_data).
fn cbComboBoxSelected(obj: *gobject.Object, _: ?*anyopaque, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    const dd: *gtk.DropDown = @ptrCast(@alignCast(obj));
    const sel = gtk.DropDown.getSelected(dd);
    if (sel == std.math.maxInt(c_uint)) return; // GTK_INVALID_LIST_POSITION
    const f = emit orelse return;
    f(node_id, "selectionChanged", .{ .index = @intCast(sel) });
    // GtkDropDown has no free-text entry, so the combo's text IS the selected
    // row; AppKit's NSComboBox fires `changed` per keystroke as well.
    if (ndDropDownSelectedText(dd)) |t| f(node_id, "changed", .{ .text = t });
}

/// `<avatar>` custom image. A missing or unreadable file leaves the initials
/// fallback in place rather than blanking the avatar.
fn ndAvatarSetImage(av: *adw.Avatar, path: []const u8, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    if (path.len == 0) {
        adw.Avatar.setCustomImage(av, null);
        return;
    }
    const tex = gdk.Texture.newFromFilename(dupeZ(path), null) orelse {
        std.debug.print("ND_WARN Avatar imagePath not loadable: {s}\n", .{path});
        return;
    };
    defer gobject.Object.unref(tex.as(gobject.Object));
    adw.Avatar.setCustomImage(av, tex.as(gdk.Paintable));
}

/// The universal `focus` command. TextArea and the list-shaped widgets hand
/// back a GtkScrolledWindow frame, so the focusable widget is the view
/// inside it, not the frame.
fn ndGrabFocus(widget: *gtk.Widget) void {
    if (!gobject.ext.isA(widget, gtk.Widget)) return; // menu node: nothing to focus
    var target = widget;
    if (gobject.ext.isA(widget, gtk.ScrolledWindow)) {
        if (scrolledWindowInner(@ptrCast(@alignCast(widget)))) |inner| target = inner;
    }
    _ = gtk.Widget.grabFocus(target);
}

/// TabView's tracked handle is the switcher+stack box, so the page signal
/// lives on the AdwViewStack inside it. The echo map is keyed by GObject,
/// which is why the `selectedIndex` apply arm blocks the STACK's handler
/// rather than the box's.
fn ndTabViewConnect(widget: *gtk.Widget, node_id: u32) void {
    const stack = ndTabViewStack(widget) orelse return;
    const data: ?*anyopaque = @ptrFromInt(@as(usize, node_id));
    const hid = gobject.signalConnectData(asObject(stack), "notify::visible-child", @ptrCast(&cbTabViewSelected), data, null, .{});
    noteSuppressible(asObject(stack), hid);
}

// notify:: handlers get (object, pspec, user_data).
fn cbTabViewSelected(obj: *gobject.Object, _: ?*anyopaque, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    const stack: *adw.ViewStack = @ptrCast(@alignCast(obj));
    const visible = adw.ViewStack.getVisibleChild(stack) orelse return;
    var i: i64 = 0;
    var child = gtk.Widget.getFirstChild(stack.as(gtk.Widget));
    while (child) |c| : (child = gtk.Widget.getNextSibling(c)) {
        if (c == visible) {
            if (emit) |f| f(node_id, "selectionChanged", .{ .index = i });
            return;
        }
        i += 1;
    }
}

const ND_DIALOG_PARENT = "nd-dialog-parent";
const ND_DIALOG_PENDING_OPEN = "nd-dialog-pending-open";
const ND_DIALOG_PRESENTED = "nd-dialog-presented";
const ND_DIALOG_PROGRAMMATIC = "nd-dialog-programmatic-close";

/// `<dialog>` and `<sheet>` are both AdwDialog: libadwaita's modal is
/// PRESENTED against a parent widget rather than packed into it, so the
/// node's handle never becomes a layout child — ndDialogAttach below is the
/// peer of ndPopoverAttach. Presentation mode is the whole difference
/// between the two: a floating window for `<dialog>`, libadwaita's own
/// bottom sheet for `<sheet>`.
fn ndDialogCreate(mode: adw.DialogPresentationMode) *gtk.Widget {
    const dlg = adw.Dialog.new();
    adw.Dialog.setPresentationMode(dlg, mode);
    return dlg.as(gtk.Widget);
}

const ND_SHEET_EDGE = "nd-sheet-edge";
const ND_SHEET_SIZE = "nd-sheet-size";

/// A `<sheet>`'s `edge`. AdwDialog knows two presentations, so `bottom` is
/// the real bottom sheet and the other three fall back to the floating
/// dialog — GNOME has no side-anchored modal panel, and inventing one out of
/// a GtkRevealer would stop looking native the moment the OS moves.
fn ndSheetPresentation(edge: []const u8) adw.DialogPresentationMode {
    return if (std.mem.eql(u8, edge, "bottom")) .bottom_sheet else .floating;
}

/// An update carries only the keys that changed, so the edge and the size
/// each have to survive an update of the other: `size` names the axis the
/// panel grows along, and which axis that is comes from the edge.
fn ndSheetSetEdge(widget: *gtk.Widget, edge: []const u8) void {
    const slot: usize = if (std.mem.eql(u8, edge, "top")) 1
    else if (std.mem.eql(u8, edge, "leading")) 2
    else if (std.mem.eql(u8, edge, "trailing")) 3
    else 4; // bottom
    gobject.Object.setData(asObject(widget), ND_SHEET_EDGE, @ptrFromInt(slot));
    adw.Dialog.setPresentationMode(@ptrCast(@alignCast(widget)), ndSheetPresentation(edge));
    ndSheetApplySize(widget, ndSheetSize(widget));
}

fn ndSheetIsSideEdge(widget: *gtk.Widget) bool {
    const raw = gobject.Object.getData(asObject(widget), ND_SHEET_EDGE) orelse return false;
    const slot = @intFromPtr(raw);
    return slot == 2 or slot == 3;
}

fn ndSheetSize(widget: *gtk.Widget) i64 {
    const raw = gobject.Object.getData(asObject(widget), ND_SHEET_SIZE) orelse return 0;
    return @intCast(@intFromPtr(raw));
}

fn ndSheetApplySize(widget: *gtk.Widget, size: i64) void {
    const dlg: *adw.Dialog = @ptrCast(@alignCast(widget));
    gobject.Object.setData(asObject(widget), ND_SHEET_SIZE, @ptrFromInt(@as(usize, @intCast(@max(size, 0)))));
    const px: c_int = if (size > 0) @intCast(size) else -1; // -1 is AdwDialog's natural size
    if (ndSheetIsSideEdge(widget)) {
        adw.Dialog.setContentWidth(dlg, px);
        adw.Dialog.setContentHeight(dlg, -1);
    } else {
        adw.Dialog.setContentHeight(dlg, px);
        adw.Dialog.setContentWidth(dlg, -1);
    }
}

/// Cross-cutting structural rule (the AdwDialog peer of ndPopoverAttach): a
/// dialog child records its tree parent as the widget to present against and
/// is never packed anywhere.
fn ndDialogAttach(child: *gtk.Widget, parent: *gtk.Widget) void {
    if (!gobject.ext.isA(parent, gtk.Widget)) return; // menu-node parent: nothing to present against
    gobject.Object.setData(asObject(child), ND_DIALOG_PARENT, parent);
}

fn ndDialogDetach(child: *gtk.Widget, parent: *gtk.Widget) void {
    if (gobject.Object.getData(asObject(child), ND_DIALOG_PARENT) != @as(?*anyopaque, parent)) return;
    ndDialogSetOpen(child, false);
    gobject.Object.setData(asObject(child), ND_DIALOG_PARENT, null);
}

/// Controlled `open`, idempotent in both directions: presented and pending
/// are tracked here, so a re-render carrying an unchanged `open` is free.
/// React mounts bottom-up, so at attach time the tree parent has not reached
/// the window yet and presenting now would open a separate toplevel instead
/// of an in-window dialog. Every open therefore waits one main-loop turn, by
/// which point the window exists.
fn ndDialogSetOpen(widget: *gtk.Widget, open: bool) void {
    const obj = asObject(widget);
    if (open) {
        if (gobject.Object.getData(obj, ND_DIALOG_PENDING_OPEN) != null) return;
        if (gobject.Object.getData(obj, ND_DIALOG_PRESENTED) != null) return;
        gobject.Object.setData(obj, ND_DIALOG_PENDING_OPEN, @ptrFromInt(1));
        _ = gobject.Object.ref(obj); // survive the turn even if React unmounts first
        _ = glib.idleAdd(&cbDialogPresentIdle, widget);
        return;
    }
    gobject.Object.setData(obj, ND_DIALOG_PENDING_OPEN, null);
    if (gobject.Object.getData(obj, ND_DIALOG_PRESENTED) == null) return;
    // forceClose, not close: `closable=false` is about the user's affordances,
    // never about the app's own control of its state.
    gobject.Object.setData(obj, ND_DIALOG_PROGRAMMATIC, @ptrFromInt(1));
    adw.Dialog.forceClose(@ptrCast(@alignCast(widget)));
}

fn cbDialogPresentIdle(data: ?*anyopaque) callconv(.c) c_int {
    const widget: *gtk.Widget = @ptrCast(@alignCast(data.?));
    const obj = asObject(widget);
    defer gobject.Object.unref(obj);
    if (gobject.Object.getData(obj, ND_DIALOG_PENDING_OPEN) == null) return 0; // closed again before the turn came round
    gobject.Object.setData(obj, ND_DIALOG_PENDING_OPEN, null);
    const parent = gobject.Object.getData(obj, ND_DIALOG_PARENT) orelse return 0; // never attached: nothing to present against
    gobject.Object.setData(obj, ND_DIALOG_PRESENTED, @ptrFromInt(1));
    adw.Dialog.present(@ptrCast(@alignCast(widget)), @ptrCast(@alignCast(parent)));
    return 0; // G_SOURCE_REMOVE
}

// ---- RichText: Markdown -> Pango markup in a GtkTextBuffer ------------------

const ND_RICH_HREF = "nd-rich-href";
const ND_RICH_SELECTABLE = "nd-rich-selectable";
const ND_RICH_NODE_ID = "nd-rich-node-id";

/// The `<richtext>` Markdown subset, parsed identically on both backends:
/// ATX headings (`#` to `######`), paragraphs (soft-wrapped lines join with a
/// space), `-`/`*`/`+` bullet lists, fenced code blocks, and the inline runs
/// `**bold**`, `__bold__`, `*italic*`, `_italic_`, `` `code` `` and
/// `[label](href)`. Everything else lands as literal text: no ordered lists,
/// block quotes, tables, images, HTML, reference links, setext headings or
/// horizontal rules. Emphasis does not nest, and a link's label is one run.
const NdRichStyle = struct {
    bold: bool = false,
    italic: bool = false,
    code: bool = false,
    heading: u8 = 0,
    href: ?[]const u8 = null,
};

const NdRichLink = struct { label: []const u8, href: []const u8, end: usize };

fn ndRichEscape(out: *std.ArrayList(u8), alloc: std.mem.Allocator, text: []const u8) void {
    for (text) |c| switch (c) {
        '&' => out.appendSlice(alloc, "&amp;") catch {},
        '<' => out.appendSlice(alloc, "&lt;") catch {},
        '>' => out.appendSlice(alloc, "&gt;") catch {},
        '"' => out.appendSlice(alloc, "&quot;") catch {},
        else => out.append(alloc, c) catch {},
    };
}

/// The accent colour as `#RRGGBB`, for the link foreground. libadwaita is the
/// authority on it, the same source the `accentColor` appearance payload uses.
fn ndAccentRgba(out: *gdk.RGBA) void {
    const rgba = adw.StyleManager.getAccentColorRgba(adw.StyleManager.getDefault());
    out.* = rgba.*;
    gdk.RGBA.free(rgba);
}

fn ndAccentHex(out: *[8]u8) []const u8 {
    var rgba: gdk.RGBA = undefined;
    ndAccentRgba(&rgba);
    const r: u8 = @intFromFloat(@min(@max(rgba.f_red, 0.0), 1.0) * 255.0);
    const g: u8 = @intFromFloat(@min(@max(rgba.f_green, 0.0), 1.0) * 255.0);
    const b: u8 = @intFromFloat(@min(@max(rgba.f_blue, 0.0), 1.0) * 255.0);
    const s = std.fmt.bufPrint(out, "#{X:0>2}{X:0>2}{X:0>2}", .{ r, g, b }) catch return "#3584E4";
    return s;
}

/// One styled run. The markup carries the look; a link ALSO gets an anonymous
/// GtkTextTag over its range carrying the href, because Pango's own `<a>`
/// attribute never reaches GtkTextView as something a click handler can read.
fn ndRichInsertRun(
    buf: *gtk.TextBuffer,
    alloc: std.mem.Allocator,
    text: []const u8,
    style: NdRichStyle,
    accent: []const u8,
    dupeZ: *const fn ([]const u8) [:0]const u8,
) void {
    if (text.len == 0) return;
    var markup: std.ArrayList(u8) = .empty;
    defer markup.deinit(alloc);
    if (style.href != null) {
        markup.appendSlice(alloc, "<span underline=\"single\" foreground=\"") catch {};
        markup.appendSlice(alloc, accent) catch {};
        markup.appendSlice(alloc, "\">") catch {};
    }
    if (style.heading > 0) {
        const size: []const u8 = switch (style.heading) {
            1 => "x-large",
            2 => "large",
            else => "medium",
        };
        markup.appendSlice(alloc, "<span size=\"") catch {};
        markup.appendSlice(alloc, size) catch {};
        markup.appendSlice(alloc, "\" weight=\"bold\">") catch {};
    }
    if (style.code) markup.appendSlice(alloc, "<tt>") catch {};
    if (style.bold) markup.appendSlice(alloc, "<b>") catch {};
    if (style.italic) markup.appendSlice(alloc, "<i>") catch {};
    ndRichEscape(&markup, alloc, text);
    if (style.italic) markup.appendSlice(alloc, "</i>") catch {};
    if (style.bold) markup.appendSlice(alloc, "</b>") catch {};
    if (style.code) markup.appendSlice(alloc, "</tt>") catch {};
    if (style.heading > 0) markup.appendSlice(alloc, "</span>") catch {};
    if (style.href != null) markup.appendSlice(alloc, "</span>") catch {};

    const z = alloc.dupeZ(u8, markup.items) catch return;
    defer alloc.free(z);
    const start_off = gtk.TextBuffer.getCharCount(buf);
    var end_iter: gtk.TextIter = undefined;
    gtk.TextBuffer.getEndIter(buf, &end_iter);
    gtk.TextBuffer.insertMarkup(buf, &end_iter, z, -1);

    const href = style.href orelse return;
    const tag = gtk.TextTag.new(null);
    gobject.Object.setData(asObject(tag), ND_RICH_HREF, @ptrCast(@constCast(dupeZ(href).ptr)));
    _ = gtk.TextTagTable.add(gtk.TextBuffer.getTagTable(buf), tag);
    gobject.Object.unref(asObject(tag)); // the table holds the ref now
    var from: gtk.TextIter = undefined;
    var to: gtk.TextIter = undefined;
    gtk.TextBuffer.getIterAtOffset(buf, &from, start_off);
    gtk.TextBuffer.getEndIter(buf, &to);
    gtk.TextBuffer.applyTag(buf, tag, &from, &to);
}

fn ndRichParseLink(text: []const u8, start: usize) ?NdRichLink {
    const close_bracket = std.mem.indexOfScalarPos(u8, text, start + 1, ']') orelse return null;
    if (close_bracket + 1 >= text.len or text[close_bracket + 1] != '(') return null;
    const close_paren = std.mem.indexOfScalarPos(u8, text, close_bracket + 2, ')') orelse return null;
    return .{
        .label = text[start + 1 .. close_bracket],
        .href = text[close_bracket + 2 .. close_paren],
        .end = close_paren + 1,
    };
}

/// Inline scan over one block's text. `base` carries the block-level look
/// (a heading's size and weight), which every run inherits.
fn ndRichInline(
    buf: *gtk.TextBuffer,
    alloc: std.mem.Allocator,
    text: []const u8,
    base: NdRichStyle,
    accent: []const u8,
    dupeZ: *const fn ([]const u8) [:0]const u8,
) void {
    var i: usize = 0;
    var plain: usize = 0;
    while (i < text.len) {
        if (text[i] == '`') {
            if (std.mem.indexOfScalarPos(u8, text, i + 1, '`')) |close| {
                ndRichInsertRun(buf, alloc, text[plain..i], base, accent, dupeZ);
                var run = base;
                run.code = true;
                ndRichInsertRun(buf, alloc, text[i + 1 .. close], run, accent, dupeZ);
                i = close + 1;
                plain = i;
                continue;
            }
        }
        if (text[i] == '[') {
            if (ndRichParseLink(text, i)) |link| {
                ndRichInsertRun(buf, alloc, text[plain..i], base, accent, dupeZ);
                var run = base;
                run.href = link.href;
                ndRichInsertRun(buf, alloc, link.label, run, accent, dupeZ);
                i = link.end;
                plain = i;
                continue;
            }
        }
        if (text[i] == '*' or text[i] == '_') {
            const strong = i + 1 < text.len and text[i + 1] == text[i];
            const marker = text[i .. i + @as(usize, if (strong) 2 else 1)];
            const body = i + marker.len;
            if (body < text.len) {
                if (std.mem.indexOfPos(u8, text, body, marker)) |close| {
                    if (close > body) {
                        ndRichInsertRun(buf, alloc, text[plain..i], base, accent, dupeZ);
                        var run = base;
                        if (strong) run.bold = true else run.italic = true;
                        ndRichInsertRun(buf, alloc, text[body..close], run, accent, dupeZ);
                        i = close + marker.len;
                        plain = i;
                        continue;
                    }
                }
            }
        }
        i += 1;
    }
    ndRichInsertRun(buf, alloc, text[plain..], base, accent, dupeZ);
}

/// Blank line between blocks, skipped before the first one.
fn ndRichBlockGap(buf: *gtk.TextBuffer, first: *bool) void {
    if (first.*) {
        first.* = false;
        return;
    }
    var iter: gtk.TextIter = undefined;
    gtk.TextBuffer.getEndIter(buf, &iter);
    gtk.TextBuffer.insert(buf, &iter, "\n\n", -1);
}

fn ndRichBulletBody(line: []const u8) ?[]const u8 {
    if (line.len < 2) return null;
    if (line[0] != '-' and line[0] != '*' and line[0] != '+') return null;
    if (line[1] != ' ') return null;
    return std.mem.trimStart(u8, line[2..], " ");
}

/// A markdown update builds a WHOLE new buffer rather than clearing the old
/// one: the tag table is where the link tags live, and swapping the buffer
/// retires them all instead of growing the table on every render.
fn ndRichTextRender(view: *gtk.TextView, md: []const u8, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    const alloc = std.heap.page_allocator;
    var accent_buf: [8]u8 = undefined;
    const accent = ndAccentHex(&accent_buf);
    const buf = gtk.TextBuffer.new(null);

    var lines: std.ArrayList([]const u8) = .empty;
    defer lines.deinit(alloc);
    var split = std.mem.splitScalar(u8, md, '\n');
    while (split.next()) |raw| lines.append(alloc, std.mem.trimEnd(u8, raw, "\r")) catch {};

    var first = true;
    var i: usize = 0;
    while (i < lines.items.len) {
        const line = std.mem.trim(u8, lines.items[i], " \t");
        if (line.len == 0) {
            i += 1;
            continue;
        }
        if (std.mem.startsWith(u8, line, "```")) {
            i += 1;
            var code: std.ArrayList(u8) = .empty;
            defer code.deinit(alloc);
            while (i < lines.items.len and !std.mem.startsWith(u8, std.mem.trim(u8, lines.items[i], " \t"), "```")) : (i += 1) {
                if (code.items.len > 0) code.append(alloc, '\n') catch {};
                // Four spaces per line is the indent: GtkTextTag margins would
                // need a tag per block, and the fence is already monospaced.
                code.appendSlice(alloc, "    ") catch {};
                code.appendSlice(alloc, lines.items[i]) catch {};
            }
            if (i < lines.items.len) i += 1; // closing fence
            ndRichBlockGap(buf, &first);
            ndRichInsertRun(buf, alloc, code.items, .{ .code = true }, accent, dupeZ);
            continue;
        }
        if (line[0] == '#') {
            var level: usize = 0;
            while (level < line.len and line[level] == '#') : (level += 1) {}
            if (level <= 6 and level < line.len and line[level] == ' ') {
                ndRichBlockGap(buf, &first);
                ndRichInline(buf, alloc, std.mem.trim(u8, line[level + 1 ..], " "), .{ .heading = @intCast(level) }, accent, dupeZ);
                i += 1;
                continue;
            }
        }
        if (ndRichBulletBody(line)) |body| {
            ndRichBlockGap(buf, &first);
            ndRichInsertRun(buf, alloc, "\u{2022} ", .{}, accent, dupeZ);
            ndRichInline(buf, alloc, body, .{}, accent, dupeZ);
            i += 1;
            while (i < lines.items.len) {
                const next = std.mem.trim(u8, lines.items[i], " \t");
                const next_body = ndRichBulletBody(next) orelse break;
                ndRichInsertRun(buf, alloc, "\n\u{2022} ", .{}, accent, dupeZ);
                ndRichInline(buf, alloc, next_body, .{}, accent, dupeZ);
                i += 1;
            }
            continue;
        }
        var para: std.ArrayList(u8) = .empty;
        defer para.deinit(alloc);
        while (i < lines.items.len) {
            const p = std.mem.trim(u8, lines.items[i], " \t");
            if (p.len == 0) break;
            if (p[0] == '#' or std.mem.startsWith(u8, p, "```") or ndRichBulletBody(p) != null) break;
            if (para.items.len > 0) para.append(alloc, ' ') catch {};
            para.appendSlice(alloc, p) catch {};
            i += 1;
        }
        ndRichBlockGap(buf, &first);
        ndRichInline(buf, alloc, para.items, .{}, accent, dupeZ);
    }

    gtk.TextView.setBuffer(view, buf);
    _ = gobject.signalConnectData(asObject(buf), "notify::has-selection", @ptrCast(&cbRichSelectionGuard), view, null, .{});
    gobject.Object.unref(asObject(buf)); // the view holds the ref now
}

/// GtkTextView has no "selectable" switch, so a non-selectable view collapses
/// every selection the moment one forms. The guard rides the buffer, which is
/// why ndRichTextRender reconnects it on each rebuild.
fn cbRichSelectionGuard(obj: *gobject.Object, _: ?*anyopaque, data: ?*anyopaque) callconv(.c) void {
    const view: *gtk.Widget = @ptrCast(@alignCast(data.?));
    if (gobject.Object.getData(asObject(view), ND_RICH_SELECTABLE) != null) return;
    const buf: *gtk.TextBuffer = @ptrCast(@alignCast(obj));
    if (gtk.TextBuffer.getHasSelection(buf) == 0) return;
    var iter: gtk.TextIter = undefined;
    gtk.TextBuffer.getIterAtMark(buf, &iter, gtk.TextBuffer.getInsert(buf));
    gtk.TextBuffer.selectRange(buf, &iter, &iter);
}

fn ndRichTextSetSelectable(view: *gtk.Widget, selectable: bool) void {
    gobject.Object.setData(asObject(view), ND_RICH_SELECTABLE, if (selectable) @ptrFromInt(1) else null);
    gtk.Widget.setCanFocus(view, @intFromBool(selectable));
}

/// Click-to-follow: the tag under the pointer is what names the href.
fn cbRichClicked(_: *gobject.Object, _: c_int, x: f64, y: f64, data: ?*anyopaque) callconv(.c) void {
    const view: *gtk.TextView = @ptrCast(@alignCast(data.?));
    const raw_id = gobject.Object.getData(asObject(view), ND_RICH_NODE_ID) orelse return;
    const node_id: u32 = @intCast(@intFromPtr(raw_id));
    var bx: c_int = 0;
    var by: c_int = 0;
    gtk.TextView.windowToBufferCoords(view, .widget, @intFromFloat(x), @intFromFloat(y), &bx, &by);
    var iter: gtk.TextIter = undefined;
    if (gtk.TextView.getIterAtLocation(view, &iter, bx, by) == 0) return;
    const tags: ?*glib.SList = gtk.TextIter.getTags(&iter);
    defer if (tags) |l| glib.SList.free(l);
    var node = tags;
    while (node) |n| : (node = n.f_next) {
        const tag = n.f_data orelse continue;
        const raw = gobject.Object.getData(@ptrCast(@alignCast(tag)), ND_RICH_HREF) orelse continue;
        const href: [*:0]const u8 = @ptrCast(raw);
        if (emit) |f| f(node_id, "linkActivated", .{ .text = std.mem.span(href) });
        return;
    }
}

fn ndRichTextCreate(md: []const u8, selectable: bool, dupeZ: *const fn ([]const u8) [:0]const u8) *gtk.Widget {
    const view = gtk.TextView.new();
    const vw = view.as(gtk.Widget);
    gtk.TextView.setEditable(view, 0);
    gtk.TextView.setCursorVisible(view, 0);
    gtk.TextView.setWrapMode(view, .word_char);
    gtk.TextView.setTopMargin(view, 4);
    gtk.TextView.setBottomMargin(view, 4);
    gtk.TextView.setLeftMargin(view, 4);
    gtk.TextView.setRightMargin(view, 4);
    gtk.TextView.setPixelsBelowLines(view, 2);
    ndRichTextSetSelectable(vw, selectable);
    const gesture = gtk.GestureClick.new();
    gtk.GestureSingle.setButton(gesture.as(gtk.GestureSingle), 1);
    _ = gobject.signalConnectData(asObject(gesture), "released", @ptrCast(&cbRichClicked), vw, null, .{});
    gtk.Widget.addController(vw, gesture.as(gtk.EventController));
    ndRichTextRender(view, md, dupeZ);

    // A document block sizes to its content the way a paragraph does; only a
    // long one scrolls, and only inside its own frame.
    const sw = gtk.ScrolledWindow.new();
    gtk.ScrolledWindow.setChild(sw, vw);
    gtk.ScrolledWindow.setPropagateNaturalHeight(sw, 1);
    gtk.Widget.setHexpand(sw.as(gtk.Widget), 1);
    return sw.as(gtk.Widget);
}

fn ndRichTextInner(widget: *gtk.Widget) ?*gtk.TextView {
    const inner = scrolledWindowInner(@ptrCast(@alignCast(widget))) orelse return null;
    return @ptrCast(@alignCast(inner));
}

fn ndRichTextConnect(widget: *gtk.Widget, node_id: u32) void {
    const view = ndRichTextInner(widget) orelse return;
    gobject.Object.setData(asObject(view), ND_RICH_NODE_ID, @ptrFromInt(@as(usize, node_id)));
}

// ---- ProgressCircle / Skeleton: the two controls neither toolkit ships -----

/// Object-data ints are stored offset by one, so "absent" stays distinct from
/// zero (g_object_set_data with a NULL pointer removes the entry).
fn ndDataInt(widget: *gtk.Widget, key: [*:0]const u8, fallback: i64) i64 {
    const raw = gobject.Object.getData(asObject(widget), key) orelse return fallback;
    return @as(i64, @intCast(@intFromPtr(raw))) - 1;
}

fn ndSetDataInt(widget: *gtk.Widget, key: [*:0]const u8, value: i64) void {
    gobject.Object.setData(asObject(widget), key, @ptrFromInt(@as(usize, @intCast(@max(value, 0))) + 1));
}

const ND_PC_PERMILLE = "nd-progresscircle-permille";
const ND_PC_LINE_WIDTH = "nd-progresscircle-line-width";
const ND_PC_SHOW_LABEL = "nd-progresscircle-show-label";

/// `<progresscircle>` is a GtkDrawingArea because no determinate ring exists
/// in GTK: GNOME's own apps draw this arc with Cairo, so the framework does
/// too rather than faking one out of a GtkLevelBar.
fn ndProgressCircleCreate(fraction: f64, line_width: i64, show_label: bool) *gtk.Widget {
    const area = gtk.DrawingArea.new();
    const w = area.as(gtk.Widget);
    gtk.DrawingArea.setContentWidth(area, 28);
    gtk.DrawingArea.setContentHeight(area, 28);
    ndProgressCircleSetFraction(w, fraction);
    ndSetDataInt(w, ND_PC_LINE_WIDTH, @max(line_width, 1));
    ndSetDataInt(w, ND_PC_SHOW_LABEL, @intFromBool(show_label));
    gtk.DrawingArea.setDrawFunc(area, &ndProgressCircleDraw, null, null);
    return w;
}

fn ndProgressCircleSetFraction(widget: *gtk.Widget, fraction: f64) void {
    const clamped = @min(@max(fraction, 0.0), 1.0);
    ndSetDataInt(widget, ND_PC_PERMILLE, @intFromFloat(@round(clamped * 1000.0)));
    gtk.Widget.queueDraw(widget);
}

fn ndProgressCircleDraw(area: *gtk.DrawingArea, cr: *cairo.Context, width: c_int, height: c_int, _: ?*anyopaque) callconv(.c) void {
    const widget = area.as(gtk.Widget);
    const w: f64 = @floatFromInt(width);
    const h: f64 = @floatFromInt(height);
    const lw: f64 = @floatFromInt(ndDataInt(widget, ND_PC_LINE_WIDTH, 3));
    const fraction = @as(f64, @floatFromInt(ndDataInt(widget, ND_PC_PERMILLE, 0))) / 1000.0;
    const radius = @max((@min(w, h) - lw) / 2.0, 1.0);
    const cx = w / 2.0;
    const cy = h / 2.0;

    var fg: gdk.RGBA = undefined;
    gtk.Widget.getColor(widget, &fg);
    cairo.Context.setLineWidth(cr, lw);
    cairo.Context.setLineCap(cr, .round);
    cairo.Context.newPath(cr);
    cairo.Context.setSourceRgba(cr, fg.f_red, fg.f_green, fg.f_blue, 0.15);
    cairo.Context.arc(cr, cx, cy, radius, 0.0, std.math.tau);
    cairo.Context.stroke(cr);

    if (fraction > 0.0) {
        var accent: gdk.RGBA = undefined;
        ndAccentRgba(&accent);
        cairo.Context.newPath(cr);
        cairo.Context.setSourceRgba(cr, accent.f_red, accent.f_green, accent.f_blue, accent.f_alpha);
        const start = -std.math.pi / 2.0; // 12 o'clock, clockwise
        cairo.Context.arc(cr, cx, cy, radius, start, start + std.math.tau * fraction);
        cairo.Context.stroke(cr);
    }

    if (ndDataInt(widget, ND_PC_SHOW_LABEL, 0) == 0) return;
    var text: [8]u8 = undefined;
    const percent: i64 = @intFromFloat(@round(fraction * 100.0));
    const label = std.fmt.bufPrintZ(&text, "{d}%", .{percent}) catch return;
    const layout = gtk.Widget.createPangoLayout(widget, label.ptr);
    defer gobject.Object.unref(asObject(layout));
    var tw: c_int = 0;
    var th: c_int = 0;
    pango.Layout.getPixelSize(layout, &tw, &th);
    cairo.Context.setSourceRgba(cr, fg.f_red, fg.f_green, fg.f_blue, fg.f_alpha);
    cairo.Context.moveTo(cr, cx - @as(f64, @floatFromInt(tw)) / 2.0, cy - @as(f64, @floatFromInt(th)) / 2.0);
    pangocairo.showLayout(cr, layout);
}

const ND_SKEL_RADIUS = "nd-skeleton-radius";
const ND_SKEL_TICK = "nd-skeleton-tick";
const ND_SKEL_PHASE = "nd-skeleton-phase";

fn ndSkeletonCreate(width: i64, height: i64, radius: i64, animated: bool) *gtk.Widget {
    const area = gtk.DrawingArea.new();
    const w = area.as(gtk.Widget);
    gtk.DrawingArea.setContentHeight(area, @intCast(@max(height, 1)));
    // width 0 is the "fill the row" shape a placeholder usually wants.
    // A declared width is a REQUEST, not an allocation: GtkWidget's default
    // halign is fill, so a hexpanding parent stretches the area past its
    // requested width regardless. start holds the declared width for real.
    if (width > 0) {
        gtk.DrawingArea.setContentWidth(area, @intCast(width));
        gtk.Widget.setHalign(w, .start);
    } else gtk.Widget.setHexpand(w, 1);
    ndSetDataInt(w, ND_SKEL_RADIUS, @max(radius, 0));
    gtk.DrawingArea.setDrawFunc(area, &ndSkeletonDraw, null, null);
    ndSkeletonSetAnimated(w, animated);
    return w;
}

fn ndSkeletonSetSize(widget: *gtk.Widget, width: ?i64, height: ?i64) void {
    const area: *gtk.DrawingArea = @ptrCast(@alignCast(widget));
    if (height) |h| gtk.DrawingArea.setContentHeight(area, @intCast(@max(h, 1)));
    if (width) |wd| {
        if (wd > 0) {
            gtk.Widget.setHexpand(widget, 0);
            gtk.Widget.setHalign(widget, .start); // same fill-default fix as ndSkeletonCreate
            gtk.DrawingArea.setContentWidth(area, @intCast(wd));
        } else {
            gtk.DrawingArea.setContentWidth(area, 0);
            gtk.Widget.setHexpand(widget, 1);
            gtk.Widget.setHalign(widget, .fill);
        }
    }
}

fn ndSkeletonSetAnimated(widget: *gtk.Widget, animated: bool) void {
    const obj = asObject(widget);
    // The OS switch outranks the prop: animations off means a flat block,
    // never a shimmer (src/gtk/motion.zig, shared with <chart>).
    const want = animated and ndmotion_gtk.animationsEnabled();
    const running = gobject.Object.getData(obj, ND_SKEL_TICK);
    if (want and running == null) {
        const id = gtk.Widget.addTickCallback(widget, &ndSkeletonTick, null, null);
        gobject.Object.setData(obj, ND_SKEL_TICK, @ptrFromInt(@as(usize, id) + 1));
    } else if (!want) {
        if (running) |raw| {
            gtk.Widget.removeTickCallback(widget, @intCast(@intFromPtr(raw) - 1));
            gobject.Object.setData(obj, ND_SKEL_TICK, null);
        }
        gobject.Object.setData(obj, ND_SKEL_PHASE, null);
    }
    gtk.Widget.queueDraw(widget);
}

const ND_SKEL_PERIOD_US: i64 = 1_400_000;

fn ndSkeletonTick(widget: *gtk.Widget, clock: *gdk.FrameClock, _: ?*anyopaque) callconv(.c) c_int {
    const now = gdk.FrameClock.getFrameTime(clock);
    const phase = @mod(now, ND_SKEL_PERIOD_US);
    ndSetDataInt(widget, ND_SKEL_PHASE, @divTrunc(phase * 1000, ND_SKEL_PERIOD_US));
    gtk.Widget.queueDraw(widget);
    return 1; // G_SOURCE_CONTINUE
}

fn ndRoundedRectPath(cr: *cairo.Context, w: f64, h: f64, r: f64) void {
    const radius = @min(r, @min(w, h) / 2.0);
    cairo.Context.newPath(cr);
    if (radius <= 0.0) {
        cairo.Context.rectangle(cr, 0.0, 0.0, w, h);
        cairo.Context.closePath(cr);
        return;
    }
    const half_pi = std.math.pi / 2.0;
    cairo.Context.arc(cr, w - radius, radius, radius, -half_pi, 0.0);
    cairo.Context.arc(cr, w - radius, h - radius, radius, 0.0, half_pi);
    cairo.Context.arc(cr, radius, h - radius, radius, half_pi, std.math.pi);
    cairo.Context.arc(cr, radius, radius, radius, std.math.pi, std.math.pi + half_pi);
    cairo.Context.closePath(cr);
}

fn ndSkeletonDraw(area: *gtk.DrawingArea, cr: *cairo.Context, width: c_int, height: c_int, _: ?*anyopaque) callconv(.c) void {
    const widget = area.as(gtk.Widget);
    const w: f64 = @floatFromInt(width);
    const h: f64 = @floatFromInt(height);
    var fg: gdk.RGBA = undefined;
    gtk.Widget.getColor(widget, &fg);
    ndRoundedRectPath(cr, w, h, @floatFromInt(ndDataInt(widget, ND_SKEL_RADIUS, 6)));
    if (gobject.Object.getData(asObject(widget), ND_SKEL_TICK) == null) {
        cairo.Context.setSourceRgba(cr, fg.f_red, fg.f_green, fg.f_blue, 0.12);
        cairo.Context.fill(cr);
        return;
    }
    // The highlight band is one widget wide and travels two widths, so it
    // enters and leaves the block completely on every pass.
    const phase = @as(f64, @floatFromInt(ndDataInt(widget, ND_SKEL_PHASE, 0))) / 1000.0;
    const x = -w + phase * 2.0 * w;
    const pattern = cairo.Pattern.linearCreate(x, 0.0, x + w, 0.0);
    defer cairo.Pattern.destroy(pattern);
    cairo.Pattern.gradientAddColorStopRgba(pattern, 0.0, fg.f_red, fg.f_green, fg.f_blue, 0.10);
    cairo.Pattern.gradientAddColorStopRgba(pattern, 0.5, fg.f_red, fg.f_green, fg.f_blue, 0.22);
    cairo.Pattern.gradientAddColorStopRgba(pattern, 1.0, fg.f_red, fg.f_green, fg.f_blue, 0.10);
    cairo.Context.setSource(cr, pattern);
    cairo.Context.fill(cr);
}

/// The GTK create dispatcher. Every kind goes through `createWidget`
/// below; this wrapper only adds the universal props no per-widget arm
/// should have to repeat.
pub fn create(
    app: *gtk.Application,
    kind: []const u8,
    props: ?std.json.Value,
    dupeZ: *const fn ([]const u8) [:0]const u8,
    the_window: *?*gtk.Window,
) !*gtk.Widget {
    const widget = try createWidget(app, kind, props, dupeZ, the_window);
    ndApplyTooltip(widget, props, dupeZ);
    ndApplyEnabled(widget, props);
    nddnd_gtk.applyProps(widget, props, dupeZ);
    return widget;
}

/// `tooltip` is a GtkWidget property, so one arm covers every kind. Menu
/// nodes (Menubar/Menu/MenuItem) hand back GMenu objects rather than
/// widgets, hence the type guard.
fn ndApplyTooltip(widget: *gtk.Widget, props: ?std.json.Value, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    const tip = propStr(props, "tooltip") orelse return;
    if (!gobject.ext.isA(widget, gtk.Widget)) return;
    gtk.Widget.setTooltipText(widget, if (tip.len > 0) dupeZ(tip).ptr else null);
}

/// `enabled` is GtkWidget sensitivity, so one arm covers every kind, and
/// insensitivity propagates through the subtree the way GTK draws it.
/// src/gtk/backend.zig's a11y probe reads the same bit back through
/// gtk_widget_is_sensitive, so getTree reports what the prop set.
fn ndApplyEnabled(widget: *gtk.Widget, props: ?std.json.Value) void {
    const on = propBool(props, "enabled") orelse return;
    if (!gobject.ext.isA(widget, gtk.Widget)) return;
    gtk.Widget.setSensitive(widget, @intFromBool(on));
}

/// `dupeZ` turns a wire string into a NUL-terminated GTK string using the
/// backend arena (passed by the caller).
fn createWidget(
    app: *gtk.Application,
    kind: []const u8,
    props: ?std.json.Value,
    dupeZ: *const fn ([]const u8) [:0]const u8,
    the_window: *?*gtk.Window,
) !*gtk.Widget {
    if (std.mem.eql(u8, kind, "Window")) {
        const w: c_int = @intCast(propInt(props, "defaultWidth") orelse 480);
        const h: c_int = @intCast(propInt(props, "defaultHeight") orelse 320);
        const handle = try ndtabs_gtk.createWindow(app, propStr(props, "tabGroup"), propStr(props, "presentation"), propStr(props, "title"), w, h, the_window, dupeZ);
        // toolbarStyle is macOS window-chrome vocabulary (unified/expanded/
        // preference NSToolbar shapes); GTK's native chrome is the one
        // AdwHeaderBar idiom, so the prop is deliberately inert here.
        // frameAutosaveName maps to NSWindow's session frame store; GTK4
        // dropped session geometry persistence — apps persist size via the
        // JS-side settings store instead.
        // density=compact tightens control metrics via the nd-compact CSS
        // block (src/gtk/style.zig), the peer of Tahoe's
        // prefersCompactControlSizeMetrics.
        if (propStr(props, "density")) |d| {
            if (std.mem.eql(u8, d, "compact")) gtk.Widget.addCssClass(handle, "nd-compact");
