            } else {
                const content = adw.ButtonContent.new();
                adw.ButtonContent.setIconName(content, ndicons.symbolic(dupeZ(icon)));
                adw.ButtonContent.setLabel(content, dupeZ(lbl));
                gtk.Button.setChild(tb.as(gtk.Button), content.as(gtk.Widget));
            }
        } else {
            gtk.Button.setLabel(tb.as(gtk.Button), dupeZ(lbl));
        }
        if (propBool(props, "active") orelse false) gtk.ToggleButton.setActive(tb, 1);
        return tb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "SegmentedControl")) {
        // AdwToggleGroup (adw 1.7+): exclusive option selection within a view
        // (view switchers own page navigation). options are create-only,
        // matching Select.options.
        const group = adw.ToggleGroup.new();
        if (propArray(props, "options")) |arr| {
            for (arr.items) |item| {
                if (item != .string) continue;
                const toggle = adw.Toggle.new();
                adw.Toggle.setLabel(toggle, dupeZ(item.string));
                adw.ToggleGroup.add(group, toggle);
            }
        }
        const idx = propInt(props, "selectedIndex") orelse 0;
        if (idx > 0) adw.ToggleGroup.setActive(group, @intCast(idx));
        return group.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "NumberInput")) {
        const min = propFloat(props, "min") orelse 0;
        const max = propFloat(props, "max") orelse 100;
        const step = propFloat(props, "step") orelse 1;
        const spin = gtk.SpinButton.newWithRange(min, max, step);
        gtk.SpinButton.setDigits(spin, @intCast(propInt(props, "digits") orelse 0));
        gtk.SpinButton.setWrap(spin, @intFromBool(propBool(props, "wraps") orelse false));
        gtk.SpinButton.setValue(spin, propFloat(props, "value") orelse 0);
        return spin.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "LinkButton")) {
        const uri = propStr(props, "uri") orelse "";
        const lbl = propStr(props, "label") orelse "";
        const lb = gtk.LinkButton.newWithLabel(dupeZ(uri), if (lbl.len > 0) dupeZ(lbl).ptr else null); // null label: GTK shows the URI
        if (propBool(props, "visited") orelse false) gtk.LinkButton.setVisited(lb, 1);
        if (propBool(props, "openExternal") orelse false) gobject.Object.setData(asObject(lb), "nd-open-external", @ptrFromInt(1));
        return lb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "LevelIndicator")) {
        const min = propFloat(props, "min") orelse 0;
        const max = propFloat(props, "max") orelse 1;
        const value = propFloat(props, "value") orelse 0;
        const indicator_style = propStr(props, "indicatorStyle") orelse "continuous";
        // GTK has no rating level bar, so that one style becomes a star row;
        // `relevancy` has no peer either and stays a plain continuous bar.
        if (std.mem.eql(u8, indicator_style, "rating")) return ndRatingCreate(max, value);
        const bar = gtk.LevelBar.newForInterval(min, max);
        const discrete = std.mem.eql(u8, indicator_style, "discrete") or (propBool(props, "discrete") orelse false);
        if (discrete) gtk.LevelBar.setMode(bar, .discrete);
        gtk.LevelBar.setValue(bar, value);
        ndLevelBarApplyOffsets(bar, propFloat(props, "warningValue"), propFloat(props, "criticalValue"));
        return bar.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ColorPicker")) {
        // GtkColorDialogButton (GTK 4.10+); the button stays insensitive
        // until a GtkColorDialog is set, so it is set unconditionally.
        const dialog = gtk.ColorDialog.new();
        gtk.ColorDialog.setWithAlpha(dialog, @intFromBool(propBool(props, "supportsAlpha") orelse false));
        const btn = gtk.ColorDialogButton.new(dialog); // transfer-full: button owns the dialog
        var rgba: gdk.RGBA = undefined;
        if (gdk.RGBA.parse(&rgba, dupeZ(propStr(props, "value") orelse "#000000")) != 0) gtk.ColorDialogButton.setRgba(btn, &rgba);
        return btn.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Banner")) {
        const banner = adw.Banner.new(dupeZ(propStr(props, "title") orelse ""));
        if (propStr(props, "buttonLabel")) |bl| adw.Banner.setButtonLabel(banner, dupeZ(bl));
        if (propBool(props, "revealed") orelse false) adw.Banner.setRevealed(banner, 1);
        return banner.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "MenuButton")) {
        const btn = gtk.MenuButton.new();
        const lbl = propStr(props, "label") orelse "";
        if (propStr(props, "iconName")) |icon| {
            if (lbl.len == 0) {
                gtk.MenuButton.setIconName(btn, ndicons.symbolic(dupeZ(icon)));
            } else {
                // icon+label both set: a plain icon_name/label assignment can only
                // show one of them, so give the button a custom AdwButtonContent
                // child (mirrors Button's create arm) and force the dropdown arrow
                // back on since a custom child would otherwise hide it.
                const content = adw.ButtonContent.new();
                adw.ButtonContent.setIconName(content, ndicons.symbolic(dupeZ(icon)));
                adw.ButtonContent.setLabel(content, dupeZ(lbl));
                gtk.MenuButton.setChild(btn, content.as(gtk.Widget));
                gtk.MenuButton.setAlwaysShowArrow(btn, 1);
            }
        } else if (lbl.len > 0) {
            gtk.MenuButton.setLabel(btn, dupeZ(lbl));
        }
        // Content-sized like Button/ToggleButton, not stretched to fill a
        // parent GtkBox — GtkMenuButton's composite internals otherwise
        // compute hexpand=true from its own child.
        gtk.Widget.setHexpand(btn.as(gtk.Widget), 0);
        gtk.Widget.setHalign(btn.as(gtk.Widget), .start);
        // Menu/MenuItem children arrive via the MenuButton structural arm
        // (ndMenuOwnerAppend) and become this button's GMenuModel.
        _ = gtk.Widget.signals.destroy.connect(btn.as(gtk.Widget), ?*anyopaque, &cbMenuOwnerDestroyed, null, .{});
        return btn.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "SplitButton")) {
        const btn = adw.SplitButton.new();
        const lbl = propStr(props, "label") orelse "";
        if (propStr(props, "iconName")) |icon| {
            if (lbl.len == 0) {
                adw.SplitButton.setIconName(btn, ndicons.symbolic(dupeZ(icon)));
            } else {
                // icon+label both set: AdwSplitButton's label/icon_name/child
                // properties are mutually exclusive (setting one clears the other
                // two), so a custom AdwButtonContent child is the only way to show
                // both at once (mirrors Button's create arm). The dropdown arrow is
                // its own separate button on AdwSplitButton, so it always survives.
                const content = adw.ButtonContent.new();
                adw.ButtonContent.setIconName(content, ndicons.symbolic(dupeZ(icon)));
                adw.ButtonContent.setLabel(content, dupeZ(lbl));
                adw.SplitButton.setChild(btn, content.as(gtk.Widget));
            }
        } else if (lbl.len > 0) {
            adw.SplitButton.setLabel(btn, dupeZ(lbl));
        }
        // Content-sized like Button/ToggleButton, not stretched to fill a
        // parent GtkBox — AdwSplitButton's composite internals otherwise
        // compute hexpand=true from its own children.
        gtk.Widget.setHexpand(btn.as(gtk.Widget), 0);
        gtk.Widget.setHalign(btn.as(gtk.Widget), .start);
        _ = gtk.Widget.signals.destroy.connect(btn.as(gtk.Widget), ?*anyopaque, &cbMenuOwnerDestroyed, null, .{});
        return btn.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Popover")) {
        const pop = gtk.Popover.new();
        gtk.Popover.setAutohide(pop, 1); // transient: click-outside dismisses (closed syncs `open` back)
        gtk.Popover.setPosition(pop, ndPositionFromString(propStr(props, "position") orelse "top"));
        // Anchoring happens when the tree parent appends this node (see the
        // ndPopoverAttach structural guard); a create-time open waits there.
        if (propBool(props, "open") orelse false) gobject.Object.setData(asObject(pop), ND_POPOVER_PENDING_OPEN, @ptrFromInt(1));
        return pop.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Expander")) {
        const ex = gtk.Expander.new(dupeZ(propStr(props, "label") orelse ""));
        if (propBool(props, "expanded") orelse false) gtk.Expander.setExpanded(ex, 1);
        return ex.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "StatusPage")) {
        const page = adw.StatusPage.new();
        if (propStr(props, "iconName")) |ic| adw.StatusPage.setIconName(page, ndicons.symbolic(dupeZ(ic)));
        adw.StatusPage.setTitle(page, dupeZ(propStr(props, "title") orelse ""));
        if (propStr(props, "description")) |d| adw.StatusPage.setDescription(page, dupeZ(d));
        // Multi children (action buttons) fan into one wrapping GtkBox set as
        // the page's single child — same move ToolbarView/SettingsGroup make.
        const box = gtk.Box.new(.vertical, 12);
        gtk.Widget.setHalign(box.as(gtk.Widget), .center);
        adw.StatusPage.setChild(page, box.as(gtk.Widget));
        return page.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ToastOverlay")) {
        const overlay = adw.ToastOverlay.new();
        return overlay.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "DatePicker")) {
        // displayStyle "field" has no GTK backing yet — the inline calendar
        // renders for both styles (documented asymmetry; AppKit honors it).
        const cal = gtk.Calendar.new();
        if (propStr(props, "value")) |v| {
            if (ndDateKeyFromIso(v)) |key| ndCalendarSelectKey(cal, key);
        }
        ndCalendarSetLimits(cal, propStr(props, "minDate"), propStr(props, "maxDate"));
        return cal.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Table")) {
        return ndtable_gtk.create(props, dupeZ);
    } else if (std.mem.eql(u8, kind, "TreeView")) {
        return ndtree_gtk.create(props, dupeZ);
    } else if (std.mem.eql(u8, kind, "FontPicker")) {
        const dialog = gtk.FontDialog.new();
        const btn = gtk.FontDialogButton.new(dialog); // transfer-full: button owns the dialog
        const desc = pango.FontDescription.fromString(dupeZ(propStr(props, "value") orelse "Sans 12")); // Pango font description syntax is the canonical wire value
        gtk.FontDialogButton.setFontDesc(btn, desc);
        pango.FontDescription.free(desc); // setFontDesc copies
        return btn.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Video")) {
        if (!ndVideoMediaAvailable()) {
            // GtkMediaFile's backend is a separate package on some distros
            // (e.g. gtk4-media-gstreamer) — degrade to a placeholder, like
            // WebView does without webkitgtk.
            std.debug.print("ND_WARN Video unavailable (no GTK media module; install the gstreamer GTK media backend); rendering placeholder label\n", .{});
            const label = gtk.Label.new("Video unavailable (GTK media module not installed)");
            return label.as(gtk.Widget);
        }
        const video = gtk.Video.new();
        // A video is a content surface: expand like WebView does.
        gtk.Widget.setHexpand(video.as(gtk.Widget), 1);
        gtk.Widget.setVexpand(video.as(gtk.Widget), 1);
        gtk.Video.setAutoplay(video, @intFromBool(propBool(props, "autoplay") orelse false));
        gtk.Video.setLoop(video, @intFromBool(propBool(props, "loop") orelse false));
        // `controls` is accepted but ignored: GtkVideo's overlaid controls
        // have no toggle (AppKit's AVPlayerView honors it).
        if (propStr(props, "src")) |s| { if (s.len > 0) ndVideoSetSrc(video, dupeZ(s)); }
        return video.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "TrayItem")) {
        // ND_PLATFORM_NOOP(TrayItem): not available on this platform — invisible empty box by design.
        return gtk.Box.new(.vertical, 0).as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ShareButton")) {
        // ND_PLATFORM_NOOP(ShareButton): not available on this platform — invisible empty box by design.
        return gtk.Box.new(.vertical, 0).as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Terminal")) {
        const font_size: c_int = @intCast(propInt(props, "fontSize") orelse 13);
        const font_family: ?[*:0]const u8 = if (propStr(props, "fontFamily")) |f| dupeZ(f).ptr else null;
        const palette: ?[*:0]const u8 = if (propStr(props, "palette")) |p| dupeZ(p).ptr else null;
        const fg: [*:0]const u8 = dupeZ(propStr(props, "foreground") orelse "").ptr;
        const bg: [*:0]const u8 = dupeZ(propStr(props, "background") orelse "").ptr;
        const cols: u16 = @intCast(propInt(props, "cols") orelse 80);
        const rows: u16 = @intCast(propInt(props, "rows") orelse 24);
        // SEAM: ndterm_gtk create/createRemote signatures are the published contract with src/gtk/terminal.zig (package nd-terminal-surfaces) — keep both sides byte-for-byte in sync.
        //   create(command: ?[*:0]const u8, cwd: ?[*:0]const u8, font_size: c_int, font_family: ?[*:0]const u8, palette: ?[*:0]const u8, foreground: [*:0]const u8, background: [*:0]const u8, cols: u16, rows: u16) *gtk.Widget
        //   createRemote(host: [*:0]const u8, port: u16, session_id: [*:0]const u8, ticket: [*:0]const u8, restore_scrollback: bool, font_size: c_int, font_family: ?[*:0]const u8, palette: ?[*:0]const u8, foreground: [*:0]const u8, background: [*:0]const u8, cols: u16, rows: u16) *gtk.Widget
        if (propBool(props, "remote") orelse false) {
            const host: [*:0]const u8 = if (propStr(props, "host")) |h| dupeZ(h).ptr else "127.0.0.1";
            const port: u16 = @intCast(propInt(props, "port") orelse 4618);
            const sid: [*:0]const u8 = if (propStr(props, "sessionId")) |s| dupeZ(s).ptr else "";
            const ticket: [*:0]const u8 = if (propStr(props, "ticket")) |t| dupeZ(t).ptr else "";
            const restore_scrollback = propBool(props, "restoreScrollback") orelse false;
            return ndterm_gtk.createRemote(host, port, sid, ticket, restore_scrollback, font_size, font_family, palette, fg, bg, cols, rows);
        }
        const command: ?[*:0]const u8 = if (propStr(props, "command")) |c| dupeZ(c).ptr else null;
        const cwd: ?[*:0]const u8 = if (propStr(props, "cwd")) |c| dupeZ(c).ptr else null;
        return ndterm_gtk.create(command, cwd, font_size, font_family, palette, fg, bg, cols, rows);
    } else if (std.mem.eql(u8, kind, "Paned")) {
        const vertical = if (propStr(props, "orientation")) |o| std.mem.eql(u8, o, "vertical") else false;
        const orientation: gtk.Orientation = if (vertical) .vertical else .horizontal;
        const paned = gtk.Paned.new(orientation);
        // AppKit parity (PanedController's minPaneExtent): the divider must
        // respect child minimum sizes instead of crushing a pane to zero.
        gtk.Paned.setShrinkStartChild(paned, 0);
        gtk.Paned.setShrinkEndChild(paned, 0);
        const frac = propFloat(props, "position") orelse 0.5;
        // +1: 0.0 bit-casts to the null pointer, indistinguishable from unset qdata (see cbPanedMapped).
        gobject.Object.setData(asObject(paned), ND_PANED_PENDING_FRACTION, @ptrFromInt(@as(usize, @bitCast(frac)) + 1));
        _ = gobject.signalConnectData(asObject(paned), "map", @ptrCast(&cbPanedMapped), null, null, .{});
        return paned.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "CommandPalette")) {
        return ndpalette_gtk.create(props, dupeZ);  // AdwDialog Cmd-K overlay (src/gtk/commandpalette.zig)
    } else if (std.mem.eql(u8, kind, "Avatar")) {
        const size = propInt(props, "size") orelse 32;
        const text = propStr(props, "text") orelse "";
        const show = propBool(props, "showInitials") orelse true;
        const av = adw.Avatar.new(@intCast(size), if (text.len > 0) dupeZ(text).ptr else null, @intFromBool(show));
        if (propStr(props, "imagePath")) |ip| ndAvatarSetImage(av, ip, dupeZ);
        return av.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Badge")) {
        const dot = propBool(props, "dot") orelse false;
        const text = dupeZ(propStr(props, "label") orelse "");
        const variant = propStr(props, "variant") orelse "neutral";
        return ndBadgeCreate(text, dot, variant);
    } else if (std.mem.eql(u8, kind, "Tag")) {
        const text = dupeZ(propStr(props, "label") orelse "");
        const variant = propStr(props, "variant") orelse "neutral";
        const removable = propBool(props, "removable") orelse false;
        return ndTagCreate(text, variant, removable);
    } else if (std.mem.eql(u8, kind, "Kbd")) {
        return ndKbdCreate(dupeZ(propStr(props, "keys") orelse ""));
    } else if (std.mem.eql(u8, kind, "ComboBox")) {
        const sl = gtk.StringList.new(null);
        if (propArray(props, "options")) |arr| {
            for (arr.items) |item| {
                if (item == .string) gtk.StringList.append(sl, dupeZ(item.string));
            }
        }
        const dd = gtk.DropDown.new(sl.as(gio.ListModel), null); // transfer-full: DropDown owns the model
        const expr = ndDropDownSearchExpression();
        gtk.DropDown.setExpression(dd, expr); // refs the expression
        gtk.Expression.unref(expr);
        gtk.DropDown.setEnableSearch(dd, 1);
        const idx = propInt(props, "selectedIndex") orelse 0;
        if (idx > 0) gtk.DropDown.setSelected(dd, @intCast(idx));
        if (propStr(props, "text")) |t| { if (t.len > 0) ndDropDownSelectText(dd, t); }
        // `placeholder`/`editable` have no GtkDropDown peer: its list is never
        // free-text and the button always shows the selected row. The search
        // popover above is GTK's answer to the same need.
        return dd.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Breadcrumb")) {
        const box = gtk.Box.new(.horizontal, 2);
        ndBreadcrumbSetSelected(box.as(gtk.Widget), propInt(props, "selectedIndex") orelse -1);
        ndBreadcrumbRebuild(box.as(gtk.Widget), propArray(props, "items"), dupeZ);
        return box.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Dialog")) {
        const dlg = ndDialogCreate(.floating);
        if (propStr(props, "title")) |t| adw.Dialog.setTitle(@ptrCast(@alignCast(dlg)), dupeZ(t));
        adw.Dialog.setCanClose(@ptrCast(@alignCast(dlg)), @intFromBool(propBool(props, "closable") orelse true));
        // 0 is the schema's "natural size"; AdwDialog spells that -1.
        const cw = propInt(props, "contentWidth") orelse 0;
        const ch = propInt(props, "contentHeight") orelse 0;
        adw.Dialog.setContentWidth(@ptrCast(@alignCast(dlg)), if (cw > 0) @intCast(cw) else -1);
        adw.Dialog.setContentHeight(@ptrCast(@alignCast(dlg)), if (ch > 0) @intCast(ch) else -1);
        // A create-time open waits for the tree parent (ndDialogSetOpen defers).
        if (propBool(props, "open") orelse false) ndDialogSetOpen(dlg, true);
        return dlg;
    } else if (std.mem.eql(u8, kind, "Sheet")) {
        const edge = propStr(props, "edge") orelse "bottom";
        const sheet = ndDialogCreate(ndSheetPresentation(edge));
        gobject.Object.setData(asObject(sheet), ND_SHEET_SIZE, @ptrFromInt(@as(usize, @intCast(@max(propInt(props, "size") orelse 320, 0)))));
        ndSheetSetEdge(sheet, edge);
        if (propBool(props, "open") orelse false) ndDialogSetOpen(sheet, true);
        return sheet;
    } else if (std.mem.eql(u8, kind, "RichText")) {
        return ndRichTextCreate(propStr(props, "markdown") orelse "", propBool(props, "selectable") orelse true, dupeZ);
    } else if (std.mem.eql(u8, kind, "ProgressCircle")) {
        return ndProgressCircleCreate(propFloat(props, "fraction") orelse 0, propInt(props, "lineWidth") orelse 3, propBool(props, "showLabel") orelse false);
    } else if (std.mem.eql(u8, kind, "Skeleton")) {
        return ndSkeletonCreate(propInt(props, "width") orelse 0, propInt(props, "height") orelse 16, propInt(props, "radius") orelse 6, propBool(props, "animated") orelse true);
    } else if (std.mem.eql(u8, kind, "Chart")) {
        return ndchart_gtk.create(props, propInt(props, "minContentHeight") orelse 160);
    } else if (std.mem.eql(u8, kind, "CodeEditor")) {
        return ndcode_gtk.create(props, dupeZ);
    }
    std.debug.print("ND_WARN unknown widget kind={s}\n", .{kind});
    return error.UnknownWidget;
}

/// The GTK update dispatcher for createAndUpdate props.
pub fn applyProps(widget: *gtk.Widget, kind: []const u8, props: ?std.json.Value, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    ndApplyTooltip(widget, props, dupeZ);
    ndApplyEnabled(widget, props);
    nddnd_gtk.applyProps(widget, props, dupeZ);
    if (std.mem.eql(u8, kind, "Window")) {
        if (propStr(props, "title")) |t| ndtabs_gtk.setTitle(widget, dupeZ(t));
    } else if (std.mem.eql(u8, kind, "Box")) {
        if (propInt(props, "spacing")) |s| {
            const box: *gtk.Box = @ptrCast(@alignCast(widget));
            // -1 sentinel = platform standard (6), same as the create arm.
            gtk.Box.setSpacing(box, if (s < 0) 6 else @intCast(s));
        }
    } else if (std.mem.eql(u8, kind, "Button")) {
        if (propStr(props, "label")) |l| ndButtonSetLabel(@ptrCast(@alignCast(widget)), l, dupeZ);
        if (propStr(props, "iconName")) |ic| ndButtonSetIconName(@ptrCast(@alignCast(widget)), ic, dupeZ);
        if (propStr(props, "iconData")) |d| ndButtonApplyIconData(@ptrCast(@alignCast(widget)), d, dupeZ);
        if (propBool(props, "prominent")) |pr| {
            if (pr) gtk.Widget.addCssClass(widget, "suggested-action")
            else gtk.Widget.removeCssClass(widget, "suggested-action");
        }
        if (propStr(props, "badge")) |bd| ndButtonApplyBadge(@ptrCast(@alignCast(widget)), bd, dupeZ);
        if (propStr(props, "size")) |sz| {
            gtk.Widget.removeCssClass(widget, "compact");
            gtk.Widget.removeCssClass(widget, "large");
            if (std.mem.eql(u8, sz, "small")) gtk.Widget.addCssClass(widget, "compact")
            else if (std.mem.eql(u8, sz, "large")) gtk.Widget.addCssClass(widget, "large");
        }
    } else if (std.mem.eql(u8, kind, "TextInput")) {
        if (propStr(props, "text")) |t| {
            const editable = @as(*gtk.Entry, @ptrCast(@alignCast(widget))).as(gtk.Editable);
            const cur = std.mem.span(gtk.Editable.getText(editable));
            if (!std.mem.eql(u8, cur, t)) {
                blockEcho(asObject(widget));
                gtk.Editable.setText(editable, dupeZ(t));
                unblockEcho(asObject(widget));
            }
        }
        if (propStr(props, "placeholder")) |p_| gtk.Entry.setPlaceholderText(@ptrCast(@alignCast(widget)), dupeZ(p_));
        if (propBool(props, "editable")) |e| gtk.Editable.setEditable(@as(*gtk.Entry, @ptrCast(@alignCast(widget))).as(gtk.Editable), @intFromBool(e));
    } else if (std.mem.eql(u8, kind, "TextArea")) {
        if (propStr(props, "text")) |t| {
            // The tracked handle is the GtkScrolledWindow frame (create arm).
            const view: *gtk.TextView = @ptrCast(@alignCast(scrolledWindowInner(@ptrCast(@alignCast(widget))).?));
            const buf = gtk.TextView.getBuffer(view);
            var s_it: gtk.TextIter = undefined;
            var e_it: gtk.TextIter = undefined;
            gtk.TextBuffer.getStartIter(buf, &s_it);
            gtk.TextBuffer.getEndIter(buf, &e_it);
            const cur = gtk.TextBuffer.getText(buf, &s_it, &e_it, 0);
