        if (propStr(props, "edge")) |e| ndSheetSetEdge(widget, e);
        if (propInt(props, "size")) |v| ndSheetApplySize(widget, v);
    } else if (std.mem.eql(u8, kind, "RichText")) {
        if (propStr(props, "markdown")) |md| {
            if (ndRichTextInner(widget)) |view| ndRichTextRender(view, md, dupeZ);
        }
        if (propBool(props, "selectable")) |s| {
            if (ndRichTextInner(widget)) |view| ndRichTextSetSelectable(view.as(gtk.Widget), s);
        }
    } else if (std.mem.eql(u8, kind, "ProgressCircle")) {
        if (propFloat(props, "fraction")) |f| ndProgressCircleSetFraction(widget, f);
        if (propInt(props, "lineWidth")) |lw| {
            ndSetDataInt(widget, ND_PC_LINE_WIDTH, @max(lw, 1));
            gtk.Widget.queueDraw(widget);
        }
        if (propBool(props, "showLabel")) |s| {
            ndSetDataInt(widget, ND_PC_SHOW_LABEL, @intFromBool(s));
            gtk.Widget.queueDraw(widget);
        }
    } else if (std.mem.eql(u8, kind, "Skeleton")) {
        // width and height merge in one call (absent keys keep prior state).
        ndSkeletonSetSize(widget, propInt(props, "width"), propInt(props, "height"));
        // handled together with width above (ndSkeletonSetSize merges both).
        if (propInt(props, "radius")) |r| {
            ndSetDataInt(widget, ND_SKEL_RADIUS, @max(r, 0));
            gtk.Widget.queueDraw(widget);
        }
        if (propBool(props, "animated")) |a| ndSkeletonSetAnimated(widget, a);
    } else if (std.mem.eql(u8, kind, "Chart")) {
        ndchart_gtk.applyProps(widget, props);
    } else if (std.mem.eql(u8, kind, "CodeEditor")) {
        ndcode_gtk.applyProps(widget, props, dupeZ);
    }
}

fn lvSetup(_: *gobject.Object, list_item: *gtk.ListItem, _: ?*anyopaque) callconv(.c) void {
    const label = gtk.Label.new(null);
    // A bare label leaves the row at its ~22px text height, flush at x=0.
    // GNOME list rows are 34px minimum with a 12px text inset; the margins
    // (rather than a fixed height) get there while still tracking the user's
    // font size.
    gtk.Label.setXalign(label, 0);
    gtk.Widget.setMarginStart(label.as(gtk.Widget), 12);
    gtk.Widget.setMarginEnd(label.as(gtk.Widget), 12);
    gtk.Widget.setMarginTop(label.as(gtk.Widget), 8);
    gtk.Widget.setMarginBottom(label.as(gtk.Widget), 8);
    gtk.ListItem.setChild(list_item, label.as(gtk.Widget));
}
fn lvBind(_: *gobject.Object, list_item: *gtk.ListItem, _: ?*anyopaque) callconv(.c) void {
    const child = gtk.ListItem.getChild(list_item) orelse return;
    const label: *gtk.Label = @ptrCast(@alignCast(child));
    const obj = gtk.ListItem.getItem(list_item) orelse return;
    const so: *gtk.StringObject = @ptrCast(@alignCast(obj));
    gtk.Label.setText(label, gtk.StringObject.getString(so));
}

fn cbHoverEnter(_: *gtk.EventControllerMotion, _: f64, _: f64, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    if (emit) |f| f(node_id, "hoverChanged", .{ .checked = true });
}
fn cbHoverLeave(_: *gtk.EventControllerMotion, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    if (emit) |f| f(node_id, "hoverChanged", .{ .checked = false });
}
fn ndHoverConnect(widget: *gtk.Widget, data: ?*anyopaque) void {
    const ctrl = gtk.EventControllerMotion.new();
    _ = gtk.EventControllerMotion.signals.enter.connect(ctrl, ?*anyopaque, &cbHoverEnter, data, .{});
    _ = gtk.EventControllerMotion.signals.leave.connect(ctrl, ?*anyopaque, &cbHoverLeave, data, .{});
    gtk.Widget.addController(widget, ctrl.as(gtk.EventController));
}

