        noteSuppressible(obj_NumberInput_valueChanged, hid_NumberInput_valueChanged);
    } else if (std.mem.eql(u8, kind, "LinkButton")) {
        const obj_LinkButton_activate = asObject(widget);
        const hid_LinkButton_activate = gobject.signalConnectData(obj_LinkButton_activate, "activate-link", @ptrCast(&cbLinkActivate), data, null, .{});
        _ = hid_LinkButton_activate;
