    } else if (std.mem.eql(u8, kind, "Banner")) {
        const obj_Banner_buttonClicked = asObject(widget);
        const hid_Banner_buttonClicked = gobject.signalConnectData(obj_Banner_buttonClicked, "button-clicked", @ptrCast(&cbBannerButtonClicked), data, null, .{});
        _ = hid_Banner_buttonClicked;
