        const obj_Expander_toggled = asObject(widget);
        const hid_Expander_toggled = gobject.signalConnectData(obj_Expander_toggled, "notify::expanded", @ptrCast(&cbExpanderToggled), data, null, .{});
        noteSuppressible(obj_Expander_toggled, hid_Expander_toggled);
    } else if (std.mem.eql(u8, kind, "ToastOverlay")) {
        if (emit) |f| ndtoast_gtk.connectEvents(widget, node_id, f);
    } else if (std.mem.eql(u8, kind, "DatePicker")) {
        const obj_DatePicker_dateChanged = asObject(widget);
        const hid_DatePicker_dateChanged = gobject.signalConnectData(obj_DatePicker_dateChanged, "day-selected", @ptrCast(&cbCalendarDaySelected), data, null, .{});
        noteSuppressible(obj_DatePicker_dateChanged, hid_DatePicker_dateChanged);
    } else if (std.mem.eql(u8, kind, "Table")) {
        if (emit) |f| ndtable_gtk.connectEvents(widget, node_id, f);
    } else if (std.mem.eql(u8, kind, "TreeView")) {
        if (emit) |f| ndtree_gtk.connectEvents(widget, node_id, f);
    } else if (std.mem.eql(u8, kind, "FontPicker")) {
        const obj_FontPicker_fontChanged = asObject(widget);
        const hid_FontPicker_fontChanged = gobject.signalConnectData(obj_FontPicker_fontChanged, "notify::font-desc", @ptrCast(&cbFontDesc), data, null, .{});
        noteSuppressible(obj_FontPicker_fontChanged, hid_FontPicker_fontChanged);
    } else if (std.mem.eql(u8, kind, "Terminal")) {
        if (emit) |f| ndterm_gtk.connectEvents(widget, node_id, f);
    } else if (std.mem.eql(u8, kind, "Paned")) {
        const obj_Paned_positionChanged = asObject(widget);
        const hid_Paned_positionChanged = gobject.signalConnectData(obj_Paned_positionChanged, "notify::position", @ptrCast(&cbPanedPositionChanged), data, null, .{});
        noteSuppressible(obj_Paned_positionChanged, hid_Paned_positionChanged);
    } else if (std.mem.eql(u8, kind, "CommandPalette")) {
        if (emit) |f| ndpalette_gtk.connectEvents(widget, node_id, f);
    } else if (std.mem.eql(u8, kind, "Tag")) {
        ndTagConnect(widget, node_id);
    } else if (std.mem.eql(u8, kind, "ComboBox")) {
        ndComboBoxConnect(widget, node_id);
    } else if (std.mem.eql(u8, kind, "Breadcrumb")) {
        ndBreadcrumbConnect(widget, node_id);
    } else if (std.mem.eql(u8, kind, "Dialog")) {
        const obj_Dialog_closed = asObject(widget);
        const hid_Dialog_closed = gobject.signalConnectData(obj_Dialog_closed, "closed", @ptrCast(&cbDialogClosed), data, null, .{});
        _ = hid_Dialog_closed;
    } else if (std.mem.eql(u8, kind, "Sheet")) {
        const obj_Sheet_closed = asObject(widget);
        const hid_Sheet_closed = gobject.signalConnectData(obj_Sheet_closed, "closed", @ptrCast(&cbDialogClosed), data, null, .{});
