/// App -> widget imperative commands (widgetCommand NDP frame, M14).
pub fn widgetCommand(widget: *gtk.Widget, kind: []const u8, command: []const u8, arg: ?std.json.Value) void {
    // `focus` is a GtkWidget operation, so one arm serves every kind that
    // declares it (see UNIVERSAL_COMMANDS in tools/codegen.ts).
    if (std.mem.eql(u8, command, "focus") and !std.mem.eql(u8, kind, "Terminal")) return ndGrabFocus(widget);
    if (std.mem.eql(u8, kind, "Window")) {
        if (std.mem.eql(u8, command, "showTabOverview") or std.mem.eql(u8, command, "present")) return ndtabs_gtk.command(widget, command, arg);
        nddialog_gtk.command(widget, command, arg);
    } else if (std.mem.eql(u8, kind, "WebView")) {
        ndweb_gtk.command(widget, command, arg);
    } else if (std.mem.eql(u8, kind, "ToastOverlay")) {
        ndtoast_gtk.command(widget, command, arg);
    } else if (std.mem.eql(u8, kind, "Terminal")) {
        ndterm_gtk.runCommand(widget, command, arg);
    } else {
        std.debug.print("ND_WARN widgetCommand on kind={s} with no commands\n", .{kind});
    }
}

pub fn appendChild(parent: *gtk.Widget, parent_kind: []const u8, child: *gtk.Widget, attached: protocol.Attached, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    // Cross-cutting: a Popover child anchors on its tree parent via
    // gtk_widget_set_parent, whatever the parent kind (M15).
    if (gobject.ext.isA(child, gtk.Popover)) return ndPopoverAttach(child, parent);
    // Cross-cutting: a Dialog/Sheet child records its tree parent as the
    // widget to present against, and is never packed into it.
    if (gobject.ext.isA(child, adw.Dialog)) return ndDialogAttach(child, parent);
    if (std.mem.eql(u8, parent_kind, "Window")) {
        if (!gobject.ext.isA(child, gtk.Widget)) {
            ndMenuAttachToWindow(child);
        } else ndtabs_gtk.appendToWindow(parent, child);
    } else if (std.mem.eql(u8, parent_kind, "Box")) {
        const box: *gtk.Box = @ptrCast(@alignCast(parent));
        if (gtk.Widget.getParent(child) != null) {
            // Moving an already-mounted child to the end (e.g. `insertBefore`
            // degenerating here because `before` was null — see insertBefore
            // below): `gtk_box_append` asserts the child has no parent, same
            // constraint as `insertChildAfter`. `reorderChildAfter` anchored
            // on the current last child is GTK's move-to-end primitive.
            gtk.Box.reorderChildAfter(box, child, gtk.Widget.getLastChild(parent));
        } else {
            gtk.Box.append(box, child);
        }
    } else if (std.mem.eql(u8, parent_kind, "ScrollView")) {
        gtk.ScrolledWindow.setChild(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "TabView")) {
        const stack = ndTabViewStack(parent) orelse return;
        const title: [*:0]const u8 = if (attached.tab_label) |tl| dupeZ(tl).ptr else "";
        const page = adw.ViewStack.addTitled(stack, child, null, title);
        if (attached.tab_icon) |ic| {
            if (ic.len > 0) {
                adw.ViewStackPage.setIconName(page, ndicons.symbolic(dupeZ(ic)));
                ndTabViewEnsureIconSwitcher(parent, stack);
            }
        }
    } else if (std.mem.eql(u8, parent_kind, "Grid")) {
        gtk.Grid.attach(@ptrCast(@alignCast(parent)), child, @intCast(attached.grid_column), @intCast(attached.grid_row), @intCast(attached.grid_column_span), @intCast(attached.grid_row_span));
    } else if (std.mem.eql(u8, parent_kind, "SplitView")) {
        const sv: *adw.OverlaySplitView = @ptrCast(@alignCast(parent));
        if (attached.slot) |sl| {
            if (std.mem.eql(u8, sl, "sidebar")) {
                adw.OverlaySplitView.setSidebar(sv, child);
                adw.OverlaySplitView.setShowSidebar(sv, 1); // the create arm hid the empty slot
            } else if (std.mem.eql(u8, sl, "list")) {
                const inner = ndSplitViewInner(sv);
                adw.OverlaySplitView.setSidebar(inner, child);
                adw.OverlaySplitView.setShowSidebar(inner, 1);
            } else if (std.mem.eql(u8, sl, "inspector")) {
                // Inspector pane: an end-positioned inner split's sidebar
                // (AppKit peer: NSSplitViewItem inspector).
                const inspector = ndSplitViewInspectorInner(sv);
                adw.OverlaySplitView.setSidebar(inspector, child);
                adw.OverlaySplitView.setShowSidebar(inspector, 1);
            } else adw.OverlaySplitView.setContent(ndSplitViewContentTarget(sv), child);
        } else adw.OverlaySplitView.setContent(ndSplitViewContentTarget(sv), child);
    } else if (std.mem.eql(u8, parent_kind, "HeaderBar")) {
        const hb: *adw.HeaderBar = @ptrCast(@alignCast(parent));
        if (gobject.ext.isA(child, gtk.SearchEntry) and adw.HeaderBar.getTitleWidget(hb) == null) {
            gtk.Widget.setHexpand(child, 1); // claim the center box's free run, not natural width
            adw.HeaderBar.setTitleWidget(hb, child);
            adw.HeaderBar.setShowTitle(hb, 1); // the title-less create arm disabled it
        } else if (attached.slot) |sl| {
            if (std.mem.eql(u8, sl, "end")) adw.HeaderBar.packEnd(hb, child)
            else adw.HeaderBar.packStart(hb, child);
        } else adw.HeaderBar.packStart(hb, child);
    } else if (std.mem.eql(u8, parent_kind, "ToolbarView")) {
        const tv: *adw.ToolbarView = @ptrCast(@alignCast(parent));
        if (gobject.ext.isA(child, adw.HeaderBar)) {
            adw.ToolbarView.addTopBar(tv, child);
            ndtabs_gtk.onHeaderBarAttached(tv, child);
        } else if (attached.slot) |sl| {
            if (std.mem.eql(u8, sl, "top")) {
                adw.ToolbarView.addTopBar(tv, child);
            } else if (std.mem.eql(u8, sl, "bottom")) {
                adw.ToolbarView.addBottomBar(tv, child);
            } else adw.ToolbarView.setContent(tv, child);
        } else adw.ToolbarView.setContent(tv, child);
    } else if (std.mem.eql(u8, parent_kind, "Menubar")) {
        ndMenubarAppendMenu(parent, child);
    } else if (std.mem.eql(u8, parent_kind, "Menu")) {
        ndMenuAppendItem(parent, child);
    } else if (std.mem.eql(u8, parent_kind, "SettingsGroup")) {
        const group: *adw.PreferencesGroup = @ptrCast(@alignCast(parent));
        if (gtk.Widget.getParent(child) != null) {
            _ = gobject.Object.ref(asObject(child));
            adw.PreferencesGroup.remove(group, child);
            adw.PreferencesGroup.add(group, child);
            gobject.Object.unref(asObject(child));
        } else adw.PreferencesGroup.add(group, child);
    } else if (std.mem.eql(u8, parent_kind, "Row")) {
        const row: *adw.ActionRow = @ptrCast(@alignCast(parent));
        gtk.Widget.setValign(child, .center);
        if (attached.slot) |sl| {
            if (std.mem.eql(u8, sl, "prefix")) {
                adw.ActionRow.addPrefix(row, child);
            } else adw.ActionRow.addSuffix(row, child);
        } else adw.ActionRow.addSuffix(row, child);
    } else if (std.mem.eql(u8, parent_kind, "Clamp")) {
        adw.Clamp.setChild(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "MenuButton")) {
        ndMenuOwnerAppend(parent, child);
    } else if (std.mem.eql(u8, parent_kind, "SplitButton")) {
        ndMenuOwnerAppend(parent, child);
    } else if (std.mem.eql(u8, parent_kind, "Popover")) {
        gtk.Popover.setChild(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "Expander")) {
        gtk.Expander.setChild(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "StatusPage")) {
        const page: *adw.StatusPage = @ptrCast(@alignCast(parent));
        const box: *gtk.Box = @ptrCast(@alignCast(adw.StatusPage.getChild(page).?));
        if (gtk.Widget.getParent(child) != null) gtk.Box.reorderChildAfter(box, child, gtk.Widget.getLastChild(box.as(gtk.Widget)))
        else gtk.Box.append(box, child);
    } else if (std.mem.eql(u8, parent_kind, "ToastOverlay")) {
        adw.ToastOverlay.setChild(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "TrayItem")) {
        // ND_PLATFORM_NOOP(TrayItem): children never mount on this platform.
    } else if (std.mem.eql(u8, parent_kind, "Paned")) {
        const p: *gtk.Paned = @ptrCast(@alignCast(parent));
        if (gtk.Paned.getStartChild(p) == null) {
            gtk.Paned.setStartChild(p, child);
        } else {
            gtk.Paned.setEndChild(p, child);
        }
    } else if (std.mem.eql(u8, parent_kind, "Dialog")) {
        adw.Dialog.setChild(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "Sheet")) {
        adw.Dialog.setChild(@ptrCast(@alignCast(parent)), child);
    } else {
        std.debug.print("ND_WARN append to non-container kind={s}\n", .{parent_kind});
    }
}

pub fn insertBefore(parent: *gtk.Widget, parent_kind: []const u8, child: *gtk.Widget, before: ?*gtk.Widget, attached: protocol.Attached, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    // null `before` degenerates to append everywhere (matches the M4 hand-written contract).
    const b = before orelse return appendChild(parent, parent_kind, child, attached, dupeZ);
    // Cross-cutting: a Popover child is position-independent — sibling order
    // never matters for an anchored popover (M15), nor for a presented dialog.
    if (gobject.ext.isA(child, gtk.Popover)) return ndPopoverAttach(child, parent);
    if (gobject.ext.isA(child, adw.Dialog)) return ndDialogAttach(child, parent);
    if (std.mem.eql(u8, parent_kind, "Box")) {
        const box: *gtk.Box = @ptrCast(@alignCast(parent));
        const prev = gtk.Widget.getPrevSibling(b);
        if (gtk.Widget.getParent(child) != null) {
            // Reordering an already-mounted child (e.g. a pin-sort), not a
            // fresh insert: `gtk_box_insert_child_after` asserts the child
            // has no parent and would silently no-op (Gtk-CRITICAL) here.
            // `reorderChildAfter` is GTK's dedicated move primitive — it
            // repositions the child in place with no unparent, so it can't
            // cascade-destroy the moved child's own children (the M8 GC
            // lesson: unparenting an interior node destroys its subtree).
            gtk.Box.reorderChildAfter(box, child, prev);
        } else {
            gtk.Box.insertChildAfter(box, child, prev);
        }
    } else if (std.mem.eql(u8, parent_kind, "TabView")) {
        // `b` unused: AdwViewStack cannot insert at an index — append (see template comment).
        const stack = ndTabViewStack(parent) orelse return;
        const title: [*:0]const u8 = if (attached.tab_label) |tl| dupeZ(tl).ptr else "";
        const page = adw.ViewStack.addTitled(stack, child, null, title);
        if (attached.tab_icon) |ic| {
            if (ic.len > 0) {
                adw.ViewStackPage.setIconName(page, ndicons.symbolic(dupeZ(ic)));
                ndTabViewEnsureIconSwitcher(parent, stack);
            }
        }
    } else if (std.mem.eql(u8, parent_kind, "Grid")) {
        // Grid children are position-addressed; sibling order is irrelevant.
        gtk.Grid.attach(@ptrCast(@alignCast(parent)), child, @intCast(attached.grid_column), @intCast(attached.grid_row), @intCast(attached.grid_column_span), @intCast(attached.grid_row_span));
    } else if (std.mem.eql(u8, parent_kind, "SplitView")) {
        const sv: *adw.OverlaySplitView = @ptrCast(@alignCast(parent));
        if (attached.slot) |sl| {
            if (std.mem.eql(u8, sl, "sidebar")) {
                adw.OverlaySplitView.setSidebar(sv, child);
                adw.OverlaySplitView.setShowSidebar(sv, 1); // the create arm hid the empty slot
            } else if (std.mem.eql(u8, sl, "list")) {
                const inner = ndSplitViewInner(sv);
                adw.OverlaySplitView.setSidebar(inner, child);
                adw.OverlaySplitView.setShowSidebar(inner, 1);
            } else if (std.mem.eql(u8, sl, "inspector")) {
                const inspector = ndSplitViewInspectorInner(sv);
                adw.OverlaySplitView.setSidebar(inspector, child);
                adw.OverlaySplitView.setShowSidebar(inspector, 1);
            } else adw.OverlaySplitView.setContent(ndSplitViewContentTarget(sv), child);
        } else adw.OverlaySplitView.setContent(ndSplitViewContentTarget(sv), child);
    } else if (std.mem.eql(u8, parent_kind, "HeaderBar")) {
        const hb: *adw.HeaderBar = @ptrCast(@alignCast(parent));
        if (gobject.ext.isA(child, gtk.SearchEntry) and adw.HeaderBar.getTitleWidget(hb) == null) {
            gtk.Widget.setHexpand(child, 1); // claim the center box's free run, not natural width
            adw.HeaderBar.setTitleWidget(hb, child);
            adw.HeaderBar.setShowTitle(hb, 1); // the title-less create arm disabled it
        } else if (attached.slot) |sl| {
            if (std.mem.eql(u8, sl, "end")) adw.HeaderBar.packEnd(hb, child)
            else adw.HeaderBar.packStart(hb, child);
        } else adw.HeaderBar.packStart(hb, child);
    } else if (std.mem.eql(u8, parent_kind, "SettingsGroup")) {
        // AdwPreferencesGroup cannot insert at an index: a mid-list insert
        // lands at the end (documented asymmetry; remount re-adds settle order).
        const group: *adw.PreferencesGroup = @ptrCast(@alignCast(parent));
        if (gtk.Widget.getParent(child) != null) {
            _ = gobject.Object.ref(asObject(child));
            adw.PreferencesGroup.remove(group, child);
            adw.PreferencesGroup.add(group, child);
            gobject.Object.unref(asObject(child));
        } else adw.PreferencesGroup.add(group, child);
    } else if (std.mem.eql(u8, parent_kind, "Row")) {
        const row: *adw.ActionRow = @ptrCast(@alignCast(parent));
        gtk.Widget.setValign(child, .center);
        if (attached.slot) |sl| {
            if (std.mem.eql(u8, sl, "prefix")) {
                adw.ActionRow.addPrefix(row, child);
            } else adw.ActionRow.addSuffix(row, child);
        } else adw.ActionRow.addSuffix(row, child);
    } else if (std.mem.eql(u8, parent_kind, "StatusPage")) {
        const page: *adw.StatusPage = @ptrCast(@alignCast(parent));
        const box: *gtk.Box = @ptrCast(@alignCast(adw.StatusPage.getChild(page).?));
        const prev = gtk.Widget.getPrevSibling(b);
        if (gtk.Widget.getParent(child) != null) gtk.Box.reorderChildAfter(box, child, prev)
        else gtk.Box.insertChildAfter(box, child, prev);
    } else if (std.mem.eql(u8, parent_kind, "Paned")) {
        const p: *gtk.Paned = @ptrCast(@alignCast(parent));
        if (gtk.Paned.getStartChild(p) == null) {
            gtk.Paned.setStartChild(p, child);
        } else {
            gtk.Paned.setEndChild(p, child);
        }
    } else {
        // single-child containers: insertBefore degenerates to appendChild.
        appendChild(parent, parent_kind, child, attached, dupeZ);
    }
}

pub fn removeChild(parent: *gtk.Widget, parent_kind: []const u8, child: *gtk.Widget) void {
    // Cross-cutting: detach an anchored Popover with gtk_widget_unparent —
    // it was never a layout child of any container (M15).
    if (gobject.ext.isA(child, gtk.Popover)) {
        if (gtk.Widget.getParent(child) == parent) gtk.Widget.unparent(child);
        return;
    }
    // Cross-cutting: an unmounted Dialog/Sheet closes rather than unparents —
    // it was presented against its tree parent, never packed into it.
    if (gobject.ext.isA(child, adw.Dialog)) {
        ndDialogDetach(child, parent);
        return;
    }
    // Cross-cutting: cancel a torn-down `<paned>`'s pending settle timer.
    // Additive, not a short-circuit: the ordinary container dispatch below
    // still runs (AppKit peer: ndPanedTeardown in ndRemoveChild).
    ndPanedStructuralTeardown(child);
    if (std.mem.eql(u8, parent_kind, "Window")) {
        if (gobject.ext.isA(child, gtk.Widget)) ndtabs_gtk.removeFromWindow(parent, child);
    } else if (std.mem.eql(u8, parent_kind, "Box")) {
        gtk.Box.remove(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "ScrollView")) {
        gtk.ScrolledWindow.setChild(@ptrCast(@alignCast(parent)), null);
    } else if (std.mem.eql(u8, parent_kind, "TabView")) {
        const stack = ndTabViewStack(parent) orelse return;
        adw.ViewStack.remove(stack, child);
    } else if (std.mem.eql(u8, parent_kind, "Grid")) {
        gtk.Grid.remove(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "SplitView")) {
        var host: *adw.OverlaySplitView = @ptrCast(@alignCast(parent));
        while (true) {
            if (adw.OverlaySplitView.getSidebar(host) == child) {
                adw.OverlaySplitView.setSidebar(host, null);
                adw.OverlaySplitView.setShowSidebar(host, 0); // an empty slot still allocates min-sidebar-width
                break;
            }
            const cur = adw.OverlaySplitView.getContent(host) orelse break;
            if (cur == child) {
                adw.OverlaySplitView.setContent(host, null);
                break;
            }
            if (!gobject.ext.isA(cur, adw.OverlaySplitView)) break;
            host = @ptrCast(@alignCast(cur));
        }
    } else if (std.mem.eql(u8, parent_kind, "HeaderBar")) {
        adw.HeaderBar.remove(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "ToolbarView")) {
        adw.ToolbarView.remove(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "Menubar")) {
        // M13: submenu removal rebuilds on next refresh (v1 no-op)
    } else if (std.mem.eql(u8, parent_kind, "Menu")) {
        // M13: item removal rebuilds on next refresh (v1 no-op)
    } else if (std.mem.eql(u8, parent_kind, "SettingsGroup")) {
        adw.PreferencesGroup.remove(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "Row")) {
        adw.ActionRow.remove(@ptrCast(@alignCast(parent)), child);
    } else if (std.mem.eql(u8, parent_kind, "Clamp")) {
        adw.Clamp.setChild(@ptrCast(@alignCast(parent)), null);
    } else if (std.mem.eql(u8, parent_kind, "MenuButton")) {
        ndMenuOwnerRemove(parent, child);
    } else if (std.mem.eql(u8, parent_kind, "SplitButton")) {
        ndMenuOwnerRemove(parent, child);
    } else if (std.mem.eql(u8, parent_kind, "Popover")) {
        gtk.Popover.setChild(@ptrCast(@alignCast(parent)), null);
    } else if (std.mem.eql(u8, parent_kind, "Expander")) {
        gtk.Expander.setChild(@ptrCast(@alignCast(parent)), null);
    } else if (std.mem.eql(u8, parent_kind, "StatusPage")) {
        const page: *adw.StatusPage = @ptrCast(@alignCast(parent));
        const box: *gtk.Box = @ptrCast(@alignCast(adw.StatusPage.getChild(page).?));
        gtk.Box.remove(box, child);
    } else if (std.mem.eql(u8, parent_kind, "ToastOverlay")) {
        adw.ToastOverlay.setChild(@ptrCast(@alignCast(parent)), null);
    } else if (std.mem.eql(u8, parent_kind, "TrayItem")) {
        // ND_PLATFORM_NOOP(TrayItem): children never mount on this platform.
    } else if (std.mem.eql(u8, parent_kind, "Paned")) {
        const p: *gtk.Paned = @ptrCast(@alignCast(parent));
        if (gtk.Paned.getStartChild(p) == child) {
            gtk.Paned.setStartChild(p, null);
        } else if (gtk.Paned.getEndChild(p) == child) {
            gtk.Paned.setEndChild(p, null);
        }
    } else if (std.mem.eql(u8, parent_kind, "Dialog")) {
        adw.Dialog.setChild(@ptrCast(@alignCast(parent)), null);
    } else if (std.mem.eql(u8, parent_kind, "Sheet")) {
        adw.Dialog.setChild(@ptrCast(@alignCast(parent)), null);
    } else {
        std.debug.print("ND_WARN remove from non-container kind={s}\n", .{parent_kind});
    }
}

